'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["it"]={"g-flurpruefung":["Cosa comprende un'ispezione visiva e funzionale prima dell'inizio dei lavori?","Prima della prima missione della giornata.","Controllare solo il livello del carburante e il colore del veicolo.","Controllare freni, sterzo, forcelle, pneumatici e dispositivi di sicurezza secondo le istruzioni per l'uso.","Effettuare una prova su strada con il carico sollevato.","L'ispezione giornaliera comprende le parti e le funzioni rilevanti per la sicurezza secondo le istruzioni per l'uso."],"g-rueckhalt":["Come gestite il sistema di ritenuta del conducente esistente?","Il carrello elevatore è dotato di sistema di ritenuta obbligatorio.","Usalo correttamente durante la guida.","Utilizzare solo su pavimenti irregolari.","Disattivatelo per i viaggi brevi.","I sistemi di ritenuta previsti devono essere utilizzati secondo le istruzioni del produttore; forniscono una protezione particolare in caso di eventi di ribaltamento."],"g-mangelmelden":["Cosa vale per un carrello elevatore con forca danneggiata?","Durante il controllo si nota un dente chiaramente piegato.","Se possibile, distribuire il carico sull'altro dente.","Guidare solo con carichi leggeri fino al prossimo tagliando.","Non utilizzare il carrello elevatore e segnalare il difetto alla persona responsabile.","Le attrezzature per la movimentazione del carico danneggiate possono guastarsi; I difetti legati alla sicurezza richiedono l'arresto fino al chiarimento."],"g-einweisung":["Passi a un carrello elevatore con comandi diversi. Cosa è necessario prima dell'uso?","Il funzionamento è diverso dal veicolo precedente.","Istruzioni relative all'apparecchio e rispetto delle istruzioni per l'uso.","È sempre sufficiente una breve spiegazione da parte di un collega non coinvolto.","Nessuna informazione aggiuntiva se hai la patente per il carrello elevatore.","Una qualifica generale non sostituisce la necessaria istruzione sul dispositivo effettivamente utilizzato."],"g-anbaugeraet":["Dovresti usare un allegato. Cosa controlli prima?","Una nuova attrezzatura cambia il modo in cui viene prelevato il carico.","Se l'accessorio è adatto all'omologazione del veicolo e al carico consentito.","Solo se il dispositivo può essere collegato visivamente.","Se l'allegato può essere installato senza documentazione.","Gli accessori possono modificare la capacità di carico rimanente e il centro di carico; È necessario verificare le omologazioni e le informazioni sulla capacità di carico."],"g-diagramm":["Perché ti serve il diagramma della capacità di carico?","È presente un carico pesante con il baricentro molto rivolto verso l'esterno.","Per determinare il percorso più breve.","Per valutare il carico massimo consentito in base all'altezza di sollevamento e al baricentro del carico.","Per determinare la capacità del serbatoio.","I carichi ammessi dipendono tra l'altro dalla distanza del baricentro del carico e dall'altezza di sollevamento."],"g-lastschwerpunkt":["Cosa succede tipicamente quando il centro di gravità si sposta più in avanti?","Un carico lungo sporge molto davanti alle forche.","La capacità di carico consentita può diminuire.","La capacità di carico è in costante aumento.","La distanza non ha alcuna influenza sul momento di ribaltamento.","Una distanza maggiore dal baricentro del carico aumenta il momento di ribaltamento e può ridurre la capacità di carico consentita."],"g-gabelabstand":["Come dovrebbero le forche prelevare un pallet adatto?","Vuoi prelevare un pallet caricato uniformemente.","Con i denti il ​​più vicino possibile e solo su un angolo.","Con una distanza così grande che il pallet si ribalta lateralmente.","Con adeguata distanza tra i denti e carro e area di supporto sufficienti.","Il carico deve essere sostenuto in modo sicuro e quanto più uniforme possibile sulle forche."],"g-schieflast":["Un carico è impilato in modo instabile. Cosa è giusto?","Le scatole di cartone possono cadere quando vengono sollevate.","Inizia lentamente; la carica si stabilizza.","Prima di prelevare il carico, fissarlo sufficientemente o farlo rimontare.","Sollevare il carico sopra l'altezza della testa in modo che non sia d'intralcio.","Carichi allentati o instabili possono cadere e mettere in pericolo le persone; attuare innanzitutto le misure di sicurezza."],"g-personen":["È possibile sollevare una persona con le comuni forche?","Un collega vuole raggiungere una luce.","Sì, se il collega indossa il casco.","No, solo gli impianti designati e consentiti possono essere utilizzati da persone in possesso di requisiti particolari.","Sì, se ci si avvicina solo ad una piccola altezza.","Le normali forche non sono una piattaforma di lavoro personale; Il trasporto e il sollevamento di persone sono soggetti a requisiti speciali."],"g-transporthoehe":["Come trasporti solitamente un pallet?","La strada è libera e pianeggiante.","Con il carico sollevato solo quanto necessario e secondo le istruzioni per l'uso.","Con il carico sollevato il più in alto possibile per essere visto meglio.","Con il montante di sollevamento fortemente inclinato in avanti, indipendentemente dal carico.","Una posizione di trasporto bassa riduce il rischio di ribaltamento e collisioni; Sono determinanti le istruzioni dell'apparecchio."],"g-kurvenfahrt":["Perché fare una curva veloce con il carrello elevatore è pericoloso?","Vuoi uscire rapidamente da un sentiero stretto.","Perché scarica semplicemente la batteria più velocemente.","Perché il carrello elevatore sterza meglio automaticamente.","Perché le forze laterali compromettono la stabilità e possono portare al ribaltamento.","In curva entrano in gioco forze aggiuntive; la velocità deve essere adattata al carico e alle condizioni."],"g-ladebruecke":["Cosa controlli prima di salire su un ponte di carico?","Dovresti guidare un camion.","Solo se il percorso sembra abbastanza ampio.","Capacità di carico, sostegno sicuro, protezione contro lo spostamento e messa in sicurezza del veicolo.","Solo se l'illuminazione è accesa.","I ponti di carico e i veicoli devono essere assicurati contro il movimento e adatti al carico."],"g-fussgaenger":["Come ti comporti in un incrocio confuso con i pedoni?","Le connessioni visive sono limitate.","Guidare a una velocità adeguata, fermarsi se necessario e garantire una visibilità sicura.","Rivendicare sempre il diritto di precedenza quando si trasporta un carico.","Suona il clacson e continua a guidare.","I pedoni hanno particolari esigenze di protezione; La velocità, la visibilità e la comunicazione devono essere adattate al percorso del traffico."],"g-batterieladen":["A cosa dovresti prestare particolare attenzione quando carichi la batteria del motore?","Viene utilizzata una stazione di ricarica della batteria.","Il luogo di ricarica può essere selezionato indipendentemente dalle istruzioni del produttore.","È consentito l'uso di fiamme libere finché il camion è fermo.","Area di carico adeguata, ventilazione sufficiente e specifiche del produttore, nonché protezione antincendio ed antideflagrante.","Durante la ricarica possono derivare pericoli derivanti da energia elettrica, gas e sostanze chimiche; devono essere rispettate le misure di protezione previste."],"h-beauftragt":["A quali condizioni è consentito utilizzare autonomamente una piattaforma di lavoro aereo?","Dovresti utilizzare una piattaforma di lavoro in azienda.","Se hai la patente di guida dell'auto.","Se sei idoneo, istruito o qualificato e incaricato dal datore di lavoro.","Se hai mai visto una piattaforma di lavoro.","Il datore di lavoro deve garantire l'idoneità, le qualifiche e gli incarichi conformi ai requisiti operativi."],"h-vorpruefung":["Cosa è necessario controllare prima di iniziare a lavorare con la piattaforma di lavoro aereo?","Il palco era fuori durante la notte.","Test visivo e funzionale secondo le istruzioni del produttore compresi i dispositivi di sicurezza.","Solo il colore e l'età del palco.","Se il materiale di lavoro è già sulla piattaforma.","Prima dell'uso è necessario controllare la macchina, i comandi, le funzioni di emergenza e i danni visibili secondo le istruzioni per l'uso."],"h-tragfaehigkeit":["Quali informazioni determinano il carico consentito sul cestino da lavoro?","Due persone vorrebbero portare con sé strumenti aggiuntivi.","Le persone sono libere di stimare il peso totale consentito.","Conta solo il peso della persona più pesante.","Non deve essere superata la capacità di carico specificata per persone, strumenti e materiali.","Il carico nominale si riferisce al carico totale consentito, compreso l'eventuale materiale trasportato."],"h-untergrund":["Cosa consideri prima di allestire un palco con supporti?","Stai lavorando vicino a un'area piena.","Solo alla portata del boom.","Controllare la capacità portante e la planarità del sottofondo nonché un supporto adeguato secondo le istruzioni.","Sul minor numero possibile di supporti estesi.","Un terreno insufficiente o un supporto inadeguato possono portare alla perdita di stabilità."],"h-wind":["Si alza un forte vento. Come procedi?","Ti ritrovi con un palco all'aperto.","Rispettare i limiti del produttore e, se vengono superati, interrompere il funzionamento o abbassare il cestello in modo sicuro.","Estendi la piattaforma il più possibile in modo che sia più stabile.","Reagire solo in caso di caduta di oggetti sciolti.","Le condizioni di vento consentite dal produttore costituiscono limiti di utilizzo; Il vento può creare pericolose forze aggiuntive."],"h-strom":["Devi lavorare vicino ad una linea elettrica aerea. Cos’è cruciale?","Nell'area di lavoro è presente una linea sotto tensione.","Il casco sostituisce il mantenimento della distanza di sicurezza.","Basta isolare il cestello e lavorare senza coordinazione.","Chiarire l'area pericolosa e garantire le necessarie distanze di protezione o altre misure adeguate.","La scarica elettrica è possibile anche senza contatto diretto; Le misure protettive necessarie devono essere determinate prima dell'inizio dell'operazione."],"h-notablass":["Perché è necessario conoscere la procedura di abbassamento di emergenza?","È possibile un fallimento del normale controllo.","In modo che in caso di guasto sia possibile un salvataggio sicuro in base all'apparecchio.","In modo che il dispositivo funzioni più velocemente durante il normale funzionamento.","Per sostituire i test regolari.","I comandi di emergenza, l'abbassamento di emergenza e i concetti di salvataggio devono essere conosciuti e funzionanti prima dell'uso."],"h-gelaender":["Come si ottiene un'altezza aggiuntiva nel cestino da lavoro?","Un punto di montaggio è appena fuori dalla tua portata.","Salite sul recinto del canestro.","Posiziona una tavola sulla ringhiera.","Utilizzare una piattaforma adatta con un'altezza di lavoro sufficiente; non salire sulle ringhiere.","Arrampicarsi sulla recinzione o effettuare altezze improvvisate mette a rischio la protezione anticaduta."],"h-psaga":["Quali requisiti si applicano ai dispositivi personali di protezione anticaduta?","Si utilizza una piattaforma di lavoro per la quale è previsto un sistema di ritenuta.","Qualsiasi punto di ancoraggio esterno al canestro è sempre sufficiente.","Osservare la valutazione dei rischi, le informazioni del produttore e i punti di ancoraggio adeguati.","Non utilizzare alcuna sicurezza se il cestino ha una ringhiera.","Se e quali DPI siano necessari dipende dalla valutazione dei rischi, dalla costruzione dello stage e dalle istruzioni operative."],"h-verfahren":["È possibile spostare il palco con la pedana sollevata?","Il posto di lavoro è a pochi metri di distanza.","Solo se il modello e le condizioni operative lo consentono secondo le indicazioni del produttore.","Sempre, purché tutti tengano duro.","No, mai indipendentemente dal design e dall'approvazione del produttore.","Il movimento in posizione sollevata dipende dal dispositivo ed è consentito solo nelle condizioni operative approvate."],"h-kollision":["Cosa è necessario organizzare quando si lavora vicino a gru o altre macchine?","Le parti in movimento potrebbero raggiungere il cestello di lavoro.","Niente; il cestino da lavoro è sempre visibile.","Guidare sempre il cestello da lavoro sopra le altre macchine.","Coordinare le aree di lavoro per evitare collisioni o punti di schiacciamento.","Il funzionamento simultaneo della macchina richiede processi di lavoro coordinati e protezione contro collisioni o inceppamenti."],"h-einstieg":["Come si entra o si esce dal cestino del lavoro?","Raggiungi il canestro a livello del suolo.","Salire sulla ringhiera esterna.","Attraverso l'accesso previsto in una posizione sicura secondo le istruzioni per l'uso.","Tramite una scala posta accanto ad essa con il braccio esteso.","È necessario rispettare l'accesso previsto e le istruzioni del produttore; Il superamento incontrollato comporta il rischio di caduta."],"h-defekt":["Il dispositivo di arresto di emergenza non funziona. Cosa fai?","Scoprirai il difetto durante l'ispezione.","Non utilizzare la piattaforma e segnalare il difetto.","Continua a lavorare se i controlli normali funzionano.","Nastro l'interruttore in modo che nessuno lo aziona.","Il guasto di un dispositivo di sicurezza è un difetto rilevante per la sicurezza e impedisce un funzionamento sicuro."],"h-sicht":["Il movimento di guida non può essere visto a causa di un ostacolo. Come procedi?","Dovresti spostare un palco mobile.","Guidare lentamente senza visibilità.","Basta affidarsi all'indicatore di distanza.","Arrestare il movimento e garantire visibilità o istruzioni sicure secondo le istruzioni operative.","Prima della procedura è necessario sorvegliare in sicurezza le persone, gli ostacoli e le vie di circolazione."],"h-rettung":["Cosa comporta la pianificazione dell'implementazione quando si lavora ad altezze maggiori?","Il palco viene utilizzato in un'area remota.","Solo la durata lavorativa prevista.","Un concetto di salvataggio adeguato con persone accessibili e addestrate e procedure di abbassamento di emergenza.","Il presupposto che i vigili del fuoco risolveranno immediatamente qualsiasi problema.","Un salvataggio efficace deve essere organizzato in anticipo, anche se i normali controlli falliscono."],"k-befaehigung":["Cosa è necessario per azionare una gru in modo indipendente?","Un nuovo dipendente dovrebbe subentrare nei lavori con la gru.","Idoneità e qualifiche richieste, istruzione e incarico corrispondente.","È sufficiente la patente di guida dell'auto.","Guardarlo una volta è sufficiente.","I lavori con la gru possono essere affidati solo a persone qualificate ed autorizzate; L'istruzione dell'attrezzatura ne fa parte."],"k-funktionspruefung":["Cosa occorre per controllare la gru prima dell'inizio del turno?","Prendi il controllo di una gru da interni.","Basta leggere il tempo di funzionamento sulla targhetta.","Controllare le funzioni rilevanti per la sicurezza e i difetti visibili secondo le istruzioni per l'uso.","Testare la gru con il carico massimo senza verificare.","Il controllo operativo obbligatorio serve a identificare tempestivamente i difetti pericolosi."],"k-traglast":["Qual è il significato della capacità di carico consentita?","Bisogna sollevare un carico.","Si tratta di una raccomandazione non vincolante.","Si applica solo quando il gancio è completamente retratto.","La capacità di carico consentita per la rispettiva condizione operativa non deve essere superata.","I carichi ammessi per alcuni tipi di gru possono dipendere dal raggio, dalla posizione del braccio e dall'armamento."],"k-personen":["Cosa vale per le persone sotto carichi sospesi?","Il carico viene spostato su un'area di lavoro.","La zona pericolosa deve essere tenuta sgombra; nessuno può passare sotto il carico sospeso.","Un casco ti permette di stare direttamente sotto di esso.","Sono ammessi brevi attraversamenti se la gru si muove lentamente.","I carichi sospesi presentano rischio di caduta e schiacciamento; Le persone devono essere tenute lontane dall'area pericolosa."],"k-signale":["Non puoi vedere l'aggressore e ricevi segnali contraddittori. Cosa fai?","La comunicazione non è chiara.","Continuare l'ultimo comando di azionamento.","Fermare il movimento e chiarire chiaramente la comunicazione.","Deposita il carico più velocemente, senza consultazione.","I movimenti sicuri del carico richiedono segnali chiari e una comunicazione chiara."],"k-sicht":["Chi fornirà supporto durante il trasporto se l'operatore della gru non riesce a vedere completamente il percorso del carico?","Un pilastro del corridoio oscura il percorso.","Una persona che passa senza previo accordo.","Nessuno; solo il gancio è importante.","Una persona adatta e istruita con una comprensione chiaramente concordata.","Se il percorso del carico non è visibile, sono necessarie istruzioni appropriate o un'altra soluzione sicura."],"k-ruck":["Perché dovrebbero essere evitati i movimenti a scatti della gru?","Un carico pesante inizia a oscillare.","Creano ulteriori sollecitazioni dinamiche e possono destabilizzare il carico.","Fondamentalmente riducono qualsiasi movimento del pendolo.","Aumentano sempre la capacità di carico nominale.","Le forze di accelerazione e frenatura aumentano la sollecitazione della gru e delle imbracature."],"k-sperrbereich":["Cosa dovresti controllare prima di spostare un carico in un'area condivisa?","Altri dipendenti lavorano nelle vicinanze.","Se il carico corrisponde visivamente alla gru.","Se l'area pericolosa è protetta e nessuna persona è a rischio.","Se il carico può essere trasportato il più in alto possibile sopra tutti.","I percorsi di rotazione e di carico devono essere liberi da persone non protette."],"k-stuetzen":["Che cosa è fondamentale per una gru mobile con stabilizzatori?","Una gru è posizionata su un terreno parzialmente riempito.","Solo la larghezza della strada.","Il colore delle piastre di supporto.","Base portante, supporto e distribuzione del carico secondo le istruzioni di installazione e del produttore.","L'installazione ha un'influenza significativa sulla stabilità, soprattutto in condizioni di terreno mutevoli."],"k-wetter":["Una folata di vento fa oscillare notevolmente il carico. Cosa è giusto?","Lavori all'aperto.","Arrestare il movimento in modo sicuro e rispettare le condizioni operative consentite.","Accelera rapidamente il movimento.","Continuare a sollevare il carico nonostante si superino i limiti del produttore.","Il vento e i movimenti oscillanti possono destabilizzare il carico e la gru; I limiti dell'applicazione devono essere rispettati."],"k-freileitung":["Cosa vale quando si utilizzano gru vicino a linee elettriche aeree?","Il braccio o il carico potrebbero avvicinarsi alla linea.","Con un carico non conduttivo le distanze non sono importanti.","Chiarire con i responsabili l'area pericolosa e le misure di protezione necessarie prima di iniziare il lavoro.","Affidatevi solo alla reazione dell'operatore della gru.","Esistono pericoli derivanti da scariche di contatto e di tensione; sono necessarie distanze protettive di sicurezza o altre misure."],"k-sichern":["Cosa fai prima di scendere dalla gru?","Il lavoro è interrotto.","Lasciare il carico sospeso.","Lasciare la gru incustodita con la trasmissione in funzione.","Abbassare il carico in modo sicuro e fissare la gru secondo le istruzioni operative.","I carichi sospesi non devono essere lasciati incontrollati; La gru e il carico devono essere parcheggiati in modo sicuro."],"k-lastanschlag":["Come fai a sapere se l'imbracatura utilizzata è adatta?","Il carico deve essere sollevato utilizzando una cinghia di sollevamento.","In termini di marcatura, capacità di carico, stato e idoneità al tipo di attacco.","Proprio dal colore della cinghia di sollevamento.","Perché era già stato utilizzato ieri.","La capacità e le condizioni di carico devono essere sufficienti, tenendo conto delle condizioni di fissaggio."],"k-stopp":["Una persona entra inaspettatamente nel percorso di caricamento. Cosa fai?","La gru sta attualmente spostando un carico.","Arrestare immediatamente il movimento in sicurezza e far sgomberare la zona pericolosa.","Basta dare un segnale di avvertimento e continuare a guidare.","Sollevare il carico più in alto e passarci sopra.","Le persone devono essere protette dai movimenti del carico; Se esiste un pericolo immediato, il movimento deve essere interrotto."],"k-neuerkran":["Riceverai una gru con un controllo sconosciuto. Cosa è giusto?","I controlli sono diversi rispetto a prima.","Prova i soliti tasti se sospetti.","Consentire a qualcun altro senza formazione di guidare avanti.","Ricevere le istruzioni necessarie relative al dispositivo prima dell'uso indipendente.","Anche gli operatori di gru esperti necessitano di conoscere i comandi specifici utilizzati, i dispositivi di protezione e i limiti."],"a-kennzeichnung":["Come si conosce la capacità di carico ammissibile di un'imbracatura?","Vuoi scegliere una fionda.","L'odore del materiale.","Sulla marcatura della capacità di carico appropriata e leggibile e sulle informazioni del produttore.","Sulla durata del tempo di conservazione.","La capacità di carico consentita è determinata dall'etichettatura e dalle condizioni operative."],"a-sichtpruefung":["Noti un taglio netto nella cinghia di sollevamento. Come procedi?","La fascia dovrebbe trasportare un carico.","Non utilizzare il nastro e inviarlo per il test o per il rifiuto.","Copri il taglio con del nastro adesivo.","Utilizzatelo solo per carichi particolarmente leggeri.","Le imbracature tessili danneggiate possono cedere e devono essere valutate secondo i criteri di scarto."],"a-neigungswinkel":["Cosa succede se l'angolo di inclinazione dei trefoli dell'imbracatura è maggiore della verticale?","Una gruccia a due capi si allarga di più.","Le forze del filamento diminuiscono sempre.","Le forze del filamento rimangono le stesse.","Le forze nei trefoli aumentano; È necessario rispettare gli angoli e le capacità di carico consentiti.","All'aumentare della diffusione, aumenta la forza di trazione per trefolo di supporto."],"a-schwerpunkt":["Perché è necessario conoscere il baricentro del carico?","Il carico è accumulato in modo non uniforme.","In modo che il carico rimanga stabile durante il sollevamento e non si ribalti in modo incontrollabile.","Selezionare il colore delle fettucce.","In modo che il carico possa essere ruotato più velocemente.","Punti di attacco sfavorevoli o la posizione del baricentro possono provocare ribaltamenti, scivolamenti o pendenze."],"a-kantenschutz":["Una cinghia di sollevamento è posizionata contro il bordo tagliente di un componente. Cosa si dovrebbe fare?","Il componente dovrebbe essere sollevato.","Sollevare rapidamente il carico prima che la cinghia si danneggi.","Utilizzare un'adeguata protezione dei bordi e verificare il tipo di fissaggio.","Pulire la superficie di carico solo con un panno.","Gli spigoli vivi possono danneggiare le fibre di supporto; i dispositivi di imbracatura devono essere adeguatamente protetti."],"a-haken":["A cosa presti attenzione quando attacchi una fionda?","Usi un gancio da carico.","Posizionare l'imbracatura sul lato della punta del gancio.","Mantenere lo sportello di sicurezza sempre aperto.","Caricare il gancio come previsto nella base del gancio e rispettare i dispositivi di sicurezza.","Un carico non consentito sulla punta del gancio e un fissaggio insufficiente possono provocarne lo sgancio."],"a-knoten":["È possibile accorciare una cinghia di sollevamento troppo lunga con un nodo?","La lunghezza della fermata non è adatta.","NO; Utilizzare solo un tipo di imbracatura adatto e approvato o un'attrezzatura di imbracatura adatta.","Sì, se il nodo è tirato molto stretto.","Sì, purché il carico sia attualmente fermo.","I nodi possono indebolire notevolmente le imbracature tessili e non sono consentite regolazioni improvvisate della lunghezza."],"a-probehub":["Perché inizialmente il carico viene sollevato con attenzione?","Vuoi trasportare in sicurezza.","In modo che possa spostarsi il più rapidamente possibile.","Per verificare la posizione delle imbracature, la stabilità ed il baricentro.","Perché la capacità di carico aumenta automaticamente.","Una prima corsa controllata aiuta a rilevare arresti errati e posizioni di carico instabili."],"a-lastweg":["Dove possono soggiornare le persone durante il trasporto del carico?","Il carico viene spostato con una gru.","Direttamente sotto il carico con un casco protettivo.","Sul peso se riescono a resistere.","All'esterno dell'area pericolosa e non sotto carichi sospesi.","Anche con un fissaggio accurato sussiste il pericolo di caduta o oscillazione dei carichi."],"a-haende":["Come evitare gli infortuni da schiacciamento durante lo svezzamento?","Il carico si avvicina alla superficie di appoggio.","Tenere mani e piedi lontani dalla zona di frantumazione e utilizzare ausili adeguati.","Tieni il carico a mani nude.","Posizionarsi tra il carico e il muro per correggere la posizione.","Tra il carico e il supporto si creano punti pericolosi di schiacciamento."],"a-vierstraenge":["Cosa vale per la distribuzione del carico su una sospensione a quattro gambe senza compensazione del carico?","È attaccato un carico rigido.","Tutti e quattro i filamenti portano inevitabilmente la stessa quantità.","Senza prova di una distribuzione uniforme, la capacità portante non può essere utilizzata come stima generale per quattro trefoli ugualmente caricati.","L'angolo di inclinazione è quindi irrilevante.","Con carichi rigidi è possibile un carico disuguale dei trefoli; La progettazione e la capacità di carico consentita devono tenerne conto."],"a-chemikalien":["Cosa si applica quando si utilizzano imbracature tessili a contatto con sostanze chimiche?","Stai lavorando con un liquido sconosciuto.","Il colore del cinturino mostra in modo affidabile la sua durata.","Ogni fascia tessile è resistente a tutti gli agenti chimici.","Controllare la durabilità e le informazioni del produttore; Non utilizzare mezzi non idonei.","I prodotti chimici possono attaccare le imbracature e ridurne inosservate la capacità di carico."],"a-aufbewahrung":["Come vengono conservate le imbracature dopo l'uso?","La missione è finita.","Pulito, asciutto e protetto da danni secondo le specifiche del produttore.","Bloccato a terra sotto un carico non protetto.","Su qualsiasi gancio esterno affilato.","Uno stoccaggio adeguato previene l'usura prematura e facilita l'ispezione visiva."],"a-auswahl":["A cosa bisogna prestare particolare attenzione quando si ha a che fare con carichi sensibili o con spigoli vivi?","È necessario spostare un componente verniciato della macchina.","Solo la velocità di trasporto.","Imbracature e misure di protezione adeguate per la superficie di carico e i bordi.","Qualunque sia il carico, sempre lo stesso cavo d'acciaio.","Il tipo di attacco e il materiale devono corrispondere alla geometria, alla superficie e al pericolo."],"a-abstimmung":["L'operatore della gru non ti vede. Come dai le istruzioni?","Ti viene assegnato come attaccante.","Agiti a piacimento finché non inizia un movimento.","Fai solo una chiamata e te ne vai.","Tramite segnali chiaramente concordati o altra comunicazione affidabile.","Gli aggressori e gli operatori delle gru devono comunicare chiaramente; Se non è chiaro, il movimento deve essere interrotto."],"b-qualifikation":["Di cosa ha bisogno una persona per utilizzare in sicurezza un escavatore idraulico durante il funzionamento?","Una nuova persona dovrebbe subentrare nei lavori di cantiere.","Qualifiche adeguate, istruzioni relative al dispositivo e incarico richiesto.","Solo la patente per l'auto.","Solo una rapida osservazione dell'operazione.","Il datore di lavoro deve garantire le qualifiche necessarie e istruire adeguatamente l'operatore per il compito."],"b-pruefung":["Cosa è compreso nell'ispezione giornaliera della macchina?","Prendi il controllo di un escavatore.","Controllare il colore della vernice e il rivestimento dei sedili.","Ispezione visiva e test funzionali secondo le istruzioni per l'uso, ad esempio per perdite e danni.","Muovere il braccio alla massima velocità finché non si ferma.","Danni all'impianto idraulico, al telaio e ai dispositivi di sicurezza possono causare gravi incidenti."],"b-leitungen":["Cosa è necessario sapere sui tubi sotterranei prima dello scavo?","Dovresti scavare un fossato.","Solo la profondità approssimativa dello scavo previsto.","È sufficiente il colore della segnaletica fuori terra.","Chiarire l'ubicazione delle possibili linee e determinare adeguate misure di sicurezza ed esplorazione.","Se danneggiati, i tubi dell'elettricità, del gas o dell'acqua possono avere conseguenze mortali."],"b-schwenkbereich":["Come si proteggono le persone nell'area di rotazione dell'escavatore?","Raccogli il materiale con il braccio.","Delimitare o mettere in sicurezza la zona pericolosa e tenere lontane le persone.","Prima di ruotare, muovere lentamente la pala.","Passare sopra l'area sopra le teste.","La sovrastruttura girevole e le attrezzature di lavoro creano rischi di schiacciamento e impatto."],"b-boeschung":["Cosa è importante quando si lavora vicino al bordo di uno scavo?","L'escavatore si trova su un terreno consolidato o riempito.","Soltanto la profondità di scavo determina il posizionamento consentito.","Prestare attenzione alla portata e al fissaggio del bordo nonché alle distanze richieste in base alla valutazione del rischio.","Guida il più vicino possibile al bordo per risparmiare distanza.","Se lo spazio libero o il terreno stabile sono insufficienti, il terrapieno potrebbe cedere e la macchina potrebbe cadere."],"b-standsicherheit":["Perché la pendenza e il terreno sono cruciali per l'utilizzo?","Il cantiere è in pendenza.","La macchina è ugualmente stabile su qualsiasi superficie.","I sottocarri cingolati eliminano qualsiasi rischio di ribaltamento.","Irregolarità e pendenze possono influire sulla stabilità; Rispettare i limiti di applicazione.","La stabilità e la sicurezza contro il ribaltamento dipendono dal pavimento, dall'attrezzatura, dal carico e dalla posizione della macchina."],"b-wechselgeraet":["Cosa controlli dopo aver sostituito la benna di un escavatore utilizzando un attacco rapido?","È stato installato un nuovo allegato.","Se è bloccato e protetto correttamente secondo le istruzioni per l'uso.","Solo se il colore della pala corrisponde.","Se l'idraulica funziona nel modo più silenzioso possibile.","I blocchi difettosi possono causare la caduta degli accessori."],"b-heben":["A cosa bisogna prestare attenzione quando si solleva un carico sospeso con un escavatore?","L'escavatore viene utilizzato per operazioni di sollevamento.","Solo la solita forza di scavo è decisiva.","Rispettare il carico di sollevamento consentito, i punti di attacco adeguati e i dispositivi di protezione prescritti.","Il carico può essere agganciato ai denti della benna.","Il sollevamento è consentito solo nelle condizioni operative previste con attrezzature adeguate."],"b-rueckwaerts":["Devi fare retromarcia, ma non puoi vedere il percorso. Cosa è giusto?","Altri lavoratori sono nelle vicinanze.","Partire con attenzione senza visibilità.","Suona il clacson e continua a guidare.","Fermarsi, garantire la visibilità e la zona pericolosa o organizzare istruzioni adeguate.","La retromarcia non deve costituire pericolo per le persone; la visibilità limitata richiede misure aggiuntive."],"b-kabel":["Il braccio potrebbe avvicinarsi a una linea elettrica aerea. Cosa fai?","Lavori in un cantiere stretto.","Chiarire preventivamente con i responsabili l'area pericolosa e le misure di protezione adeguate.","Ignora la linea se il boma è verniciato.","Muovere la barra solo con particolare rapidità.","I rischi elettrici derivano dal contatto e dal flashover; sono necessarie distanze di sicurezza e misure di protezione."],"b-verlassen":["Come si parcheggia l'escavatore prima di partire?","Fai una pausa.","Lasciare il braccio fluttuare liberamente.","Deporre l'attrezzatura di lavoro in modo sicuro e proteggere la macchina da movimenti e usi non autorizzati.","Lasciare il motore acceso e la cabina aperta.","L'attrezzatura di lavoro abbassata e la protezione contro i movimenti involontari riducono il rischio di incidenti."],"b-hydraulik":["Si nota olio idraulico ad alta pressione su una linea danneggiata. Cosa è giusto?","C'è una perdita di linea.","Senti la perdita con la mano.","Collegare un nuovo morsetto sotto pressione.","Spegnere la macchina in condizioni di sicurezza, far diminuire la pressione e far eseguire le riparazioni da personale specializzato autorizzato.","Il fluido idraulico ad alta pressione può causare lesioni gravi; non controllare mai eventuali perdite manualmente."],"b-unterbau":["Qual è il pericolo di guidare su superfici instabili?","Il terreno è soffice dopo la pioggia.","La macchina può affondare, scivolare o ribaltarsi.","L'unità diventa automaticamente più ampia.","Ciò rende il campo di rotazione più sicuro.","Una capacità di carico insufficiente può compromettere notevolmente la stabilità e la sicurezza di guida."],"b-arbeitsgeraet":["Qualcuno può lavorare sotto un attrezzo sollevato?","Una persona vuole controllare qualcosa sotto la pala.","Sì, quando il motore è al minimo.","No, non senza il necessario supporto sicuro e la messa in sicurezza dell'attrezzatura di lavoro.","Sì, se la persona indossa il casco protettivo.","Le apparecchiature idrauliche possono affondare; I lavori di manutenzione richiedono attrezzature di lavoro sicure."],"b-geraeteart":["Passi da un escavatore idraulico a una pala gommata. Cosa è richiesto?","Il funzionamento e il comportamento del movimento sono diversi.","Proprio le stesse calzature.","Un giro di prova senza istruzioni.","La qualifica o l'istruzione richiesta per il nuovo tipo di macchina.","La qualifica deve corrispondere al tipo di macchina utilizzata e ai requisiti operativi specifici."],"g-neigung":["Stai guidando un carrello elevatore carico su un piano inclinato. Cos'è importante?","Il percorso ha una pendenza evidente.","Guidare sempre il carico in discesa, anche se pesante.","Guidare il carico in salita e osservare le linee guida operative per la guida in pendenza.","Indipendentemente dal senso di marcia, alzare la forcella al massimo.","Nelle salite e nelle discese il carico deve essere sempre trasportato in salita; È necessario rispettare il veicolo e le istruzioni per l'uso."],"g-gabelabsenken":["Perché è necessario abbassare la forca durante il parcheggio?","Il carrello elevatore è parcheggiato per una pausa.","In modo che altri possano usare la forchetta per salire.","In modo che la forcella rimanga più visibile a distanza.","In modo che il sollevamento del carico non comporti inutili rischi di inciampo o lesioni.","I dispositivi di presa del carico abbassati riducono il rischio di incidenti dovuti a forche sporgenti o non fissate."],"g-fahrerwechsel":["Un collega vorrebbe prendere in prestito il carrello elevatore. Cosa deve essere presente?","Il collega ha solo il tuo permesso verbale.","Deve possedere le qualifiche necessarie e un mandato operativo.","Il tuo incarico si applica automaticamente anche a lui.","Per ogni azienda è sufficiente la patente di guida per un'auto privata.","La leadership indipendente è legata all'idoneità personale, alla formazione, alle qualifiche e all'incarico operativo."],"g-ladungssicherung":["Un pallet contiene scatole sciolte e impilate. Cosa è giusto?","Una scatola di cartone può cadere durante la guida.","Assicurare il carico contro scivolamenti e cadute prima del trasporto.","Procedere lentamente solo su terreni particolarmente irregolari.","Compensare le scatole sciolte con una posizione della forca più alta.","Il carico deve essere stabile e assicurato contro la caduta prima di essere trasportato con il carrello industriale."],"g-bodenbelastung":["Di fronte a te c'è una coperta con capacità di carico limitata. Come decidi?","Il percorso si snoda su un livello intermedio.","Prestare solo attenzione al peso del camion senza carico.","Chiarire il carico sul pavimento consentito per carrelli elevatori e carichi.","Guidare con slancio in modo che il soffitto sia sotto carico per un periodo di tempo più breve.","Ciò che è rilevante è lo stress effettivo totale sull'area, compresi il veicolo, il carico e le influenze dinamiche."],"g-verkehrswege":["Un sentiero segnalato attraversa il vostro cammino. Cosa è giusto?","I pedoni possono accedere al passaggio in qualsiasi momento.","Puoi sempre rivendicare la priorità con il clacson.","È consentito passare oltre la segnaletica senza essere osservati.","Regola la velocità, presta attenzione ai pedoni e continua a guidare solo quando il percorso è libero.","Le vie di traffico devono essere guidate tenendo conto delle persone; I segnali di pericolo non sostituiscono una visibilità sicura e un percorso libero."],"g-parkbremse":["Parcheggi un carrello elevatore su un terreno pianeggiante. Cosa include?","Vuoi lasciare il posto di guida per diversi minuti.","Parcheggiare, inserire il freno di stazionamento e proteggerlo dall'uso non autorizzato.","Lasciare il veicolo solo in posizione neutra.","Lasciare la forchetta all'altezza della testa in modo che nessuno la tocchi.","Prima della partenza il veicolo deve essere fermato in sicurezza e assicurato contro movimenti involontari."],"g-typenschild":["Quali informazioni sono vincolanti per quanto riguarda il carico su un carrello elevatore?","Vuoi prendere una macchina pesante.","La capacità di carico stimata in base alle dimensioni del veicolo.","Informazioni del produttore nel diagramma di carico o capacità di carico.","Il peso dell'ultimo pallet trasportato.","Il carico consentito è determinato dalle indicazioni del produttore e dipende, tra l'altro, dal baricentro del carico e dall'altezza di sollevamento."],"g-tore":["Ti avvicini ad un passaggio basso con un carrello elevatore. Cosa stai controllando?","C'è un carico enorme sul veicolo.","Se il passaggio con carico e accessorio è possibile in tutta sicurezza.","Solo l'altezza della piastra portaforche senza carico.","Se riesci a passare più velocemente prima che il cancello si chiuda.","Prima del passaggio è necessario tenere conto dell'altezza e della larghezza libera nonché delle dimensioni del carico e del veicolo."],"g-reifen":["Durante il tuo controllo quotidiano trovi uno pneumatico gravemente danneggiato. Cosa fai?","Sul pneumatico sono visibili danni rilevanti per la sicurezza.","Guidi lentamente fino all'appuntamento di manutenzione regolare.","Aumenti la pressione dei pneumatici e continui a guidare.","Non si mette in funzione il veicolo e si denuncia il danno.","I pneumatici danneggiati possono compromettere la stabilità e la manovrabilità; il difetto deve essere chiarito prima dell'uso."],"h-absperren":["I dipendenti passano sotto la tua piattaforma di lavoro. Cosa è necessario?","Pericolo di caduta degli utensili.","Un'adeguata area protettiva o riservata sotto il posto di lavoro.","Solo un avviso al primo passaggio.","Conservare gli utensili il più lontano possibile dal bordo del cestello.","Un'area di lavoro sotto postazioni di lavoro elevate deve essere protetta dal pericolo dovuto alla caduta di parti."],"h-werkzeuge":["Come si trasportano gli attrezzi nel cestino da lavoro?","In quota sono necessari diversi piccoli strumenti.","Posizionateli liberamente sulla ringhiera in modo che siano facilmente raggiungibili.","Conservarli e fissarli in modo tale che non cadano o impediscano il funzionamento.","Attaccalo all'esterno della ringhiera in tasca.","Gli oggetti sciolti possono cadere e mettere in pericolo le persone; è necessaria un'archiviazione sicura."],"h-abstuetzung":["Un supporto poggia su un chiusino. Cosa è necessario controllare?","Vuoi alzare la piattaforma.","Assicurati solo che il coperchio sia asciutto.","Se il carico può essere assorbito in sicurezza a quel punto.","Se non è necessario utilizzare gli altri supporti.","Il sottosuolo e le zone di contatto devono essere in grado di assorbire in sicurezza le forze portanti; Le coperture dovranno essere valutate separatamente."],"h-notaus":["Quando deve essere utilizzato il dispositivo di arresto di emergenza?","Si verifica immediatamente un movimento pericoloso.","Solo alla fine di un turno regolare.","Per l'arresto in caso di grave pericolo secondo le istruzioni per l'uso.","In sostituzione dell'abbassamento previsto.","L'arresto di emergenza viene utilizzato per scongiurare il pericolo, non il consueto controllo o il normale arresto."],"h-schraegstellung":["L'avviso di inclinazione del palco risponde. Come reagisci?","La macchina si trova su una superficie inclinata.","Si ignora l'avvertimento ad altezze di lavoro basse.","Nonostante l'avvertimento, raggiungi la posizione di sollevamento più alta.","Ti fermi e porti il ​​palco in condizioni di sicurezza secondo le istruzioni del produttore.","Gli avvisi di inclinazione possono indicare una stabilità inadeguata; ulteriori spostamenti non devono aumentare il pericolo."],"h-umgebung":["Cosa è necessario organizzare quando si installa in prossimità di una zona di traffico?","I veicoli possono toccare il palco.","Protezione contro le collisioni e guida adeguata del traffico.","Far oscillare il cestello da lavoro il più lontano possibile dalla strada.","Solo una chiamata di avviso prima dell'avvio.","Le piattaforme di lavoro aeree devono essere protette dalle collisioni con gli utenti della strada; l'installazione deve essere adeguatamente protetta."],"h-ueberlast":["Viene attivato l'avviso di sovraccarico nel cestello. Cosa fai?","Sono stati invitati strumenti aggiuntivi.","Terminare il lavoro a velocità più elevata.","Stabilire il carico consentito del cestello e seguire le istruzioni del produttore.","Disattivare permanentemente il segnale di avvertimento.","Non deve essere superato il carico massimo consentito sul cestello, comprese persone e materiale."],"h-quetschen":["Chiudi il cestino sotto un tetto. Quale pericolo è particolarmente importante?","Sopra il cestino è rimasto poco spazio.","Incastro o schiacciamento tra il cestello e la struttura.","Che il motore consuma più carburante.","Che il senso di marcia si inverte sempre automaticamente.","Gli spazi ristretti sopra o accanto al cestello da lavoro possono causare gravi lesioni da schiacciamento."],"h-stromausfall":["Il palco rimane a grande altezza senza motore principale. Cosa è giusto?","Il normale controllo del cestello non risponde più.","Scendi dal boma senza sicurezza.","Aspetti fino alla fine del tuo turno senza essere informato.","Avviare il salvataggio preparato utilizzando persone addestrate e l'abbassamento di emergenza.","È necessario pianificare un salvataggio sicuro in caso di interruzioni; Le persone addestrate devono conoscere le funzioni di emergenza."],"h-transportstellung":["Come si prepara il terreno per un trasporto?","La piattaforma di lavoro aereo viene caricata su un veicolo idoneo.","Portare il braccio e la piattaforma in posizione di trasporto secondo le istruzioni operative.","Legare la piattaforma il più lontano possibile.","Lasciare i supporti estesi in modo che occupi più spazio.","La posizione di trasporto e la fissazione del carico prescritte dipendono dal produttore e dalle indicazioni di trasporto."],"k-bremsprobe":["Cosa dimostra un test funzionale del freno della gru prima dell'uso?","Vuoi essere in grado di sostenere un carico in modo sicuro.","Se il freno arresta e mantiene il movimento come previsto.","Solo se l'illuminazione della cabina funziona.","Se il gancio può sostenere automaticamente un carico.","Prima dell'uso è necessario verificare le funzioni rilevanti per la sicurezza secondo le specifiche."],"k-schraegzug":["È possibile trainare un carico lateralmente obliquamente con la gru?","Il gancio non è verticalmente sopra il carico.","Sì, se la gru dispone ancora di riserva di carico.","No, i carichi non devono essere tirati con tiri diagonali non consentiti.","Sì, se le fasce sono particolarmente corte.","La trazione diagonale può causare movimenti incontrollati e sollecitazioni aggiuntive sulla gru e sulle imbracature."],"k-verhakt":["Un carico è sospeso alla sottostruttura. Cosa è giusto?","Si avverte resistenza durante il sollevamento.","Continui a sollevare finché non viene via.","Sposti il ​​carico lateralmente a scatti.","Ti fermi e il fissaggio o il blocco vengono rimossi in modo sicuro.","I carichi bloccati non devono essere staccati con la forza, poiché potrebbero formarsi forze inaccettabili."],"k-anzuheben":["Cosa controlli quando sollevi brevemente un carico sospeso per la prima volta?","Il carico si solleva di qualche centimetro da terra.","Se rimane in equilibrio e lo stop è sicuro.","Se una persona può mettersi direttamente sotto il carico.","Se la gru diventa più stabile girando rapidamente.","Un breve sollevamento controllato viene utilizzato per verificare l'attacco, l'equilibrio e il comportamento sicuro del carico."],"k-lastweg":["Quale dovrebbe essere il percorso di trasporto del carico della gru?","Diversi luoghi di lavoro si trovano sotto il possibile percorso di carico.","Se possibile, sopra le postazioni di lavoro occupate.","Su un percorso pianificato e chiaro senza persone a rischio.","Sempre in diagonale attraverso la zona più trafficata.","I percorsi di carico devono essere organizzati in modo tale che le persone non siano messe in pericolo dai carichi sospesi."],"k-signalverlust":["Il collegamento radio con il maresciallo si interrompe. Cosa fai?","Non è possibile vedere il percorso di caricamento stesso.","Continui il movimento lentamente.","Oscilli sperimentalmente nella direzione precedente.","Arresti il ​​movimento finché non c'è una comprensione chiara e sicura.","Se manca la comunicazione, il movimento confuso del carico potrebbe non continuare."],"k-haken":["Il gancio di sicurezza non si chiude in modo affidabile. Cosa è giusto?","Durante l'ispezione si nota una chiusura difettosa.","L'errore deve essere corretto professionalmente prima di un ulteriore utilizzo.","Leghi saldamente la chiusura con una fascetta.","Utilizzi il gancio solo per carichi leggeri.","Dispositivi di fissaggio difettosi sui ganci di carico possono causare lo sgancio delle imbracature e devono essere eliminati."],"k-zugrichtung":["Cosa è importante per il sostegno verticale di un carico?","Il carico deve essere sollevato da una macchina.","Il gancio della gru deve essere allineato sopra il baricentro del carico.","Il gancio deve essere posizionato il più lateralmente possibile.","Il carico deve essere spinto prima del sollevamento.","Un effetto di forza quanto più verticale possibile al di sopra del baricentro del carico evita forze laterali inammissibili e oscillazioni incontrollate."],"k-wartung":["Sulla gru si avverte un insolito rumore stridente. Come procedi?","Il rumore si verifica durante il sollevamento.","Copri il rumore aumentando la velocità.","Interrompere le operazioni in sicurezza, segnalare i difetti e farli chiarire.","Continuare a lavorare senza preavviso fino alla pausa.","Cambiamenti evidenti possono indicare danni rilevanti per la sicurezza e richiedere un'ispezione."],"k-absetzen":["Cosa deve essere garantito durante l'abbassamento del carico della gru?","Un carico pesante è posizionato su una superficie.","Il carico può giacere non fissato su una superficie inclinata.","Le imbracature vengono rimosse mentre è ancora galleggiante.","Il carico è stabile e protetto contro il ribaltamento o lo spostamento.","Il carico può essere rilasciato dall'imbracatura solo dopo che è stato depositato in modo sicuro e dopo aver raggiunto la stabilità."],"l-schwerpunkt":["Perché è necessario conoscere il centro di gravità prima di colpire?","È necessario trasportare una macchina di forma asimmetrica.","In modo che il carico rimanga il più equilibrato possibile durante il sollevamento.","In modo che le imbracature possano essere scelte della lunghezza desiderata.","In modo che la capacità di carico consentita non abbia alcun ruolo.","La posizione del baricentro influenza la distribuzione del carico e l'equilibrio sicuro durante il sollevamento."],"l-etikett":["Una cinghia di sollevamento non dispone di un'etichetta della capacità di carico leggibile. Cosa è giusto?","La marcatura è diventata irriconoscibile.","Stimare la capacità di carico in base al colore.","Non utilizzare la cinghia di sollevamento finché non ne sia stata chiaramente dimostrata l'idoneità.","Utilizzare la cintura solo una volta per piccoli carichi.","Per le imbracature è necessaria idonea segnaletica; La capacità di carico inspiegabile preclude una selezione sicura."],"l-kantenschutz":["Su un bordo affilato in acciaio si trova una fascia tessile. Cosa è necessario?","Il carico presenta spigoli vivi.","Tirare la fascia il più strettamente possibile senza protezione.","Esegui il colpo più velocemente.","Utilizzare un'adeguata protezione dei bordi o altri dispositivi di imbracatura adeguati.","Gli spigoli vivi possono danneggiare o tagliare le imbracature tessili; è necessaria una protezione adeguata."],"l-spreizwinkel":["In che modo un angolo di inclinazione maggiore influisce sul carico sulle imbracature?","Un carico viene sollevato mediante due funi oblique.","Ad angoli meno favorevoli, le forze nei trefoli possono aumentare.","Le forze del filo scompaiono.","L'angolo non ha alcuna influenza sullo stress.","Con un angolo di arresto meno favorevole, le forze per trefolo possono aumentare; È necessario rispettare le tabelle della capacità di carico."],"l-knoten":["È possibile accorciare a piacere la corda di una fettuccia utilizzando un nodo?","La fune è troppo lunga per il carico previsto.","Sì, un nodo stretto migliora la capacità di carico.","No, utilizzare solo metodi di accorciamento e ancoraggio approvati.","Sì, se il nodo è fissato con nastro adesivo.","I nodi non ammessi indeboliscono le imbracature e ne modificano la capacità di carico consentita."],"l-zeichen":["Cosa vale per la comunicazione con la persona che utilizza la gru?","Il percorso di caricamento è parzialmente oscurato.","Molte persone danno segnali diversi contemporaneamente.","Vengono utilizzati segnali chiari e concordati in precedenza.","La comunicazione non è mai necessaria con le gru radio.","Segnali chiari e chiare responsabilità impediscono pericolosi movimenti errati."],"l-sichtpruefung":["Quando è opportuno controllare le imbracature per individuare eventuali difetti visibili?","Vuoi usare una catena da imbracatura.","Prima dell'uso prestare attenzione ad eventuali danni visibili esternamente.","Solo se è già avvenuto un incidente.","Solo una volta al primo acquisto.","Prima di ogni utilizzo è necessario valutare le condizioni di lavoro sicure; Danni visibili ne impediscono un utilizzo sicuro."],"l-drehung":["Un carico sollevato inizia a ruotare in modo incontrollabile. Cosa fai?","Il carico si sposta nel percorso di carico.","Metti la mano tra il carico e il muro.","Ti metti sotto il peso e lo tieni stretto.","Mantieni la distanza e lascia che il movimento si fermi in modo controllato.","I movimenti incontrollati del carico creano pericoli di schiacciamento e impatto; Le persone devono abbandonare l'area di pericolo."],"l-ablegen":["Quando è possibile rimuovere le imbracature dal carico?","Il carico è posizionato su cavalletti.","Se il carico è stabile e protetto contro il ribaltamento o lo spostamento.","Non appena tocca terra per la prima volta, indipendentemente dalla sua posizione.","Mentre sei ancora in bilico per risparmiare tempo.","Le imbracature possono essere rimosse solo dopo essere state posizionate in modo sicuro e stabile."],"l-ketten":["Un'imbracatura a catena ha una maglia gravemente piegata. Cosa fai?","Il danno è visibile anche prima del sollevamento.","Avvolgi l'area danneggiata con del filo metallico.","Rimuovere la catena dall'uso e farla controllare da un professionista.","Sollevare il carico solo alla metà.","Le maglie della catena deformate rappresentano un danno visibile che può impedire un utilizzo sicuro."],"b-einweiser":["Cosa è importante quando la visibilità dall'escavatore è limitata?","Una parte dell'edificio oscura la zona di guida.","Misure o istruzioni visive adeguate e comunicazione chiara.","Basta guardare il cofano.","Attraversa l'area girevole nonostante sia invisibile.","Se la visibilità è limitata, i pericoli devono essere prevenuti attraverso misure organizzative e tecniche aggiuntive."],"b-aushub":["Dove si può immagazzinare il materiale di scavo vicino ad una fossa di costruzione?","Il bordo della fossa non deve essere esposto a ulteriori rischi.","Ammucchiare direttamente sul bordo in modo che i vialetti rimangano liberi.","Conservare ad una distanza di sicurezza sufficiente e secondo le specifiche del cantiere.","Posizionare su puntellamenti sciolti senza ulteriori prove.","Il materiale di scavo può mettere in pericolo rilevati e puntellamenti a causa di carichi aggiuntivi; Dovranno essere mantenute le distanze di sicurezza."],"b-personen":["Le persone possono rimanere nell'area di rotazione mentre l'escavatore è in movimento?","Una persona vuole misurare durante il panning.","Sì, purché indossi il casco protettivo.","Sì, se l'escavatore oscilla lentamente.","No, la zona di pericolo deve essere sgombra prima dello spostamento.","Nell'area di rotazione sussiste il pericolo di gravi schiacciamenti e lesioni da impatto; la zona deve essere tenuta sgombra."],"b-ladung":["Come si trasporta il materiale in sicurezza con una pala gommata?","Una pala piena dovrebbe essere guidata attraverso il cortile.","Con una posizione di trasporto bassa e adeguata e un percorso libero.","Con pala rialzata per una migliore visibilità.","Con porte aperte e forte angolo di sterzata.","Una posizione di trasporto adeguata riduce il rischio di ribaltamento e migliora la stabilità di guida."],"b-anbaupruefung":["Cosa controllare dopo aver accoppiato un accessorio?","È stata attaccata una nuova pala.","Solo la pulizia della vernice.","Il bloccaggio sicuro e funziona secondo le istruzioni per l'uso.","Solo se il dispositivo ha lo stesso aspetto dall'esterno.","I bloccaggi errati degli attacchi rapidi possono portare al rilascio involontario degli accessori."],"b-einstieg":["Come entrare in sicurezza nella cabina dell'escavatore?","I gradini sono sporchi dopo la pioggia.","Salite sulla cabina tramite il boma.","Sali sui bruchi con un solo salto.","Utilizzare gradini e appigli designati e pulire i gradini sporchi.","Salite adeguate e punti di aggancio sicuri riducono il rischio di scivolare e cadere."],"b-graben":["Il muro di una trincea presenta crepe e si sta sgretolando. Cosa è giusto?","Lavori proprio accanto al fossato.","Interrompere i lavori e chiedere ai responsabili di mettere in sicurezza lo scavo.","Basta avvicinarsi al bordo per chiudere il fossato.","Approfondire ulteriormente la trincea senza protezione.","Crepe e movimenti del terreno possono indicare instabilità e richiedere un'ulteriore valutazione della sicurezza."],"b-betanken":["A cosa presti attenzione quando fai rifornimento ad una macchina movimento terra?","Il serbatoio è quasi vuoto.","Proteggere il motore e le fonti di accensione secondo le istruzioni del produttore ed evitare perdite.","Fare sempre rifornimento di benzina o gasolio in cabina.","Fumare durante il rifornimento in assenza di vento.","I rischi di incendio e ambientali durante la manipolazione del carburante richiedono misure di protezione adeguate."],"b-laufwerk":["Perché i cingoli e il carro devono essere controllati regolarmente?","Noti vibrazioni insolite durante la guida.","In modo che la macchina possa muoversi più velocemente.","Perché i danni possono compromettere la guida sicura e la stabilità.","Perché il lavoro è sempre consentito senza controllo visivo.","I danni alla trasmissione possono compromettere la manovrabilità, la stabilità e il funzionamento sicuro."],"b-einweisen":["Cosa è necessario quando si lavora in prossimità del traffico pedonale pubblico?","Un escavatore lavora direttamente sul bordo di un marciapiede.","I pedoni devono muoversi autonomamente nell'area dell'altalena.","Basta attaccare un cartello sulla pala.","Delimitare efficacemente l'area pericolosa e dirigere il traffico in modo sicuro.","È vietato entrare nella zona pericolosa delle macchine movimento terra a terzi; Sono necessarie barriere e instradamenti del traffico adeguati."],"g2-fahrweg":["C'è del liquido versato sulla strada da percorrere. Come procedi?","Il carrello elevatore passerebbe direttamente sulla zona scivolosa.","Smettere di guidare e far fissare o rimuovere il punto pericoloso.","Attraversare il posto il più velocemente possibile con la forca sollevata.","Spero in gomme più asciutte e continuerò a guidare senza modifiche.","I percorsi contaminati mettono in pericolo la stabilità e devono essere adeguatamente messi in sicurezza prima di percorrerli."],"g2-sichtladung":["Un pallet alto blocca la vista davanti a noi. Cosa è giusto?","Devi guidare fino a un'area di deposito e non puoi vedere il percorso.","Solleva il pallet finché non riesci a vedere sotto di esso.","Guidare solo utilizzando metodi appropriati e sicuri, come la retromarcia con una visuale libera.","È comunque possibile guidare sulla strada senza segnaletica o senza visibilità.","La direzione di marcia e la visibilità devono consentire l'osservazione sicura del percorso di circolazione; I carichi non devono sostituire l'ispezione visiva."],"g2-fussgaengerstop":["Un pedone si ferma proprio accanto al carrello elevatore. Cosa fai?","La persona si trova nel raggio d'azione possibile di guida e rotazione.","Superare il pedone accelerando brevemente.","Superare la persona con il carico sollevato.","Fermarsi e proseguire la guida solo a distanza di sicurezza.","Le persone devono restare lontane dalla zona di pericolo; Se necessario, il viaggio deve essere interrotto."],"g2-hubmast":["Si nota una linea idraulica danneggiata sul montante di sollevamento. Cosa si applica?","L'olio idraulico perde visibilmente dall'attrezzo.","Mettere fuori servizio il carrello elevatore e segnalare il danno.","Controllare manualmente la perdita durante il sollevamento.","Sollevare solo carichi più piccoli fino alla fine del turno.","I danni idraulici possono portare a movimenti incontrollati; l'utilizzo sicuro non è garantito fino al test."],"g2-lagerregal":["Vuoi riporre un pallet su uno scaffale. Cosa controlli prima?","Il livello dello scaffale è alto e la capacità di carico deve essere mantenuta.","Spingere il pallet sullo scaffale il più rapidamente possibile.","Controllare l'idoneità del vano scaffale, del peso del carico e dello spazio libero.","Stimare il peso totale basandosi esclusivamente sul numero di scatole.","Gli scaffali e le attrezzature per il trasporto del carico devono corrispondere alla situazione di carico e di stoccaggio."],"g2-batterieschaden":["La batteria del carrello elevatore è danneggiata esternamente. Cosa è giusto?","Prima del caricamento si notano crepe o liquidi insoliti.","Coprire i danni con nastro adesivo e caricare immediatamente.","Lasciare che un'altra persona carichi la batteria senza controllarla.","Non caricare o utilizzare e informare gli specialisti responsabili.","Le batterie danneggiate comportano rischi elettrici e chimici e richiedono una valutazione professionale."],"g2-fahrerkabine":["Cosa vale per gli oggetti sciolti nell'area del conducente?","Gli attrezzi sono sul pavimento accanto ai pedali di comando.","Rimuovere gli oggetti e mantenere libera l'area operativa.","Durante la guida tenere l'utensile solo con un piede.","Nascondere le parti sciolte sotto il sedile del conducente.","Gli oggetti sciolti possono bloccare i pedali e compromettere il funzionamento sicuro del veicolo."],"g2-uebergabe":["Prendi in consegna un carrello elevatore dopo un cambio di turno. Cosa include?","L'ultimo utilizzo del veicolo è stato un collega.","Supponiamo che il collega abbia preso in carico tutti i controlli.","Effettuare l'ispezione necessaria e informarsi sui difetti noti.","Inizia il viaggio senza guardare la macchina.","La persona che lo prende in consegna deve assicurarsi che sia in condizioni di sicurezza prima dell'uso."],"g2-transportsicherung":["Un oggetto alto è allentato sul pallet. Come ti comporti?","Il carico potrebbe ribaltarsi in avanti durante la frenata.","Trasportare la forca particolarmente in alto in modo che il carico rimanga stabile.","Prendi le curve lentamente, vai dritto più velocemente.","Posizionare il carico in modo stabile e assicurarlo contro il ribaltamento o la caduta.","I carichi sciolti devono essere stabilizzati prima del trasporto in modo che i movimenti di frenata e di guida non ne causino la caduta."],"g2-arbeitsende":["Cosa è importante con un carrello elevatore non presidiato?","Finisci il tuo turno e lasci l'area.","Parcheggiare il veicolo in modo sicuro e assicurarlo contro lo spostamento e l'uso non autorizzato.","Lasciare la chiave inserita in modo che i colleghi possano trovare la macchina.","Lasciare la forchetta all'altezza degli occhi in modo che sia visibile.","Il parcheggio sicuro comprende la movimentazione del carico abbassato e la protezione contro lo spostamento e la messa in servizio non autorizzata."],"g2-bremsweg":["Perché bisogna prestare particolare attenzione allo spazio di frenata sotto carico?","Il carrello elevatore trasporta merci pesanti attraverso la corsia del magazzino.","Frenare sempre più tardi con un carico pesante che senza carico.","Adeguare la velocità alle condizioni di visibilità, del terreno e del carico.","Durante la frenata, sollevare bruscamente il carico per decelerare meglio.","La massa e le condizioni della strada influenzano lo spazio di arresto; la velocità adattata è fondamentale."],"g2-rampe":["Cosa controlli prima di salire una rampa ripida?","Il percorso potrebbe essere troppo ripido per il veicolo.","Percorrere la rampa alla massima velocità indipendentemente dalla pendenza.","Superare il bordo della rampa con il carico sollevato.","Controllare la pendenza consentita e la modalità operativa sicura dalle specifiche del veicolo.","Possono essere utilizzate solo rampe entro i limiti operativi previsti; Le istruzioni per l'uso e il controllo del carico sono determinanti."],"g2-zinke":["Un pallet è più largo della distanza delle forche. Cosa bisogna tenere in considerazione?","Hai intenzione di caricare un carico insolitamente grande.","Regolare la distanza delle forche e i punti di montaggio in base al carico.","Utilizzare solo un dente se il carico è troppo largo.","Sollevare il carico inclinandolo finché non raggiunge la posizione corretta.","L'assorbimento uniforme e adeguato del carico riduce lo scivolamento e il ribaltamento."],"g2-betriebsanweisung":["Che ruolo gioca la regolamentazione operativa del traffico?","Nel magazzino sono presenti aree pedonali e a senso unico segnalate.","Con i carrelli elevatori valgono solo le regole della strada pubblica.","Seguire i percorsi e le regole del traffico specificati.","Ignorare la segnaletica una volta caricato il veicolo.","I percorsi aziendali e le norme di sicurezza tutelano il traffico dei carrelli elevatori e le persone a piedi."],"g2-nothalt":["Lo sterzo reagisce in modo insolito durante la guida. Cosa è giusto?","Il veicolo non può più essere controllato come al solito.","Guidare a velocità più elevate per rendere lo sterzo più reattivo.","Compensare l'errore con deviazioni dello sterzo particolarmente ampie.","Fermarsi in un luogo sicuro e far controllare il veicolo.","Uno sterzo compromesso compromette la guida sicura; la macchina non deve continuare ad essere utilizzata senza controllo."],"g2-anschlagkette":["Vuoi spostare un carico sospeso con un carrello elevatore. Cosa si applica?","Il carico dovrebbe essere appeso a un gancio sotto le forche.","Solo con un dispositivo approvato e un'adeguata attrezzatura per il trasporto del carico.","Qualsiasi catena andrà bene se il carico non è pesante.","Bloccare la catena direttamente tra entrambe le forcelle.","I carichi sospesi liberamente modificano la stabilità; Sono necessarie le approvazioni del produttore e strutture adeguate."],"g2-rollenlast":["Un componente cilindrico giace su un pallet senza essere fissato. Cosa fai?","Il carico potrebbe rotolare durante il trasporto.","Avvicinarsi al pallet in modo particolarmente brusco.","Assicurare il componente contro il rotolamento prima che il pallet venga prelevato.","Posizionare i denti abbastanza in alto in modo che il componente non sia visibile.","I carichi rotondi o rotolanti richiedono una protezione affidabile contro i cambiamenti di posizione."],"g2-pruefplakette":["Come fai a sapere se il carrello elevatore può essere utilizzato?","Sulla macchina è attaccato un adesivo di ispezione.","L'eventuale adesivo sostituisce sempre l'ispezione visiva quotidiana.","La mancanza di spazio libero può essere sostituita da una guida attenta.","Oltre al controllo del veicolo è necessario tenere conto dello stato di validità del test e dell'approvazione operativa.","Test ricorrenti e controlli operativi giornalieri soddisfano diverse funzioni di sicurezza."],"g2-licht":["L'illuminazione nel magazzino si spense improvvisamente. Cosa è giusto?","Non è più possibile vedere con sicurezza gli ostacoli sul percorso.","Smettere di guidare finché non è garantita una visibilità sicura.","Aumentare la velocità di guida per uscire dall'area buia.","Continuare a guidare con le forche sollevate senza controllo visivo.","Un percorso che non può essere trascurato in sicurezza non deve essere percorso senza misure di sicurezza efficaci."],"g2-ueberhang":["Il carico si estende ben oltre il lato delle forche. Cosa stai controllando?","Vuoi trasportare il pallet attraverso un cancello stretto.","Compensare la proiezione laterale con una curva veloce.","Valutare l'altezza libera, la stabilità e la capacità di carico consentita prima di mettersi alla guida.","Guidare il carico alla massima velocità indipendentemente dalla sua forma.","Le sporgenze aumentano i rischi di collisione e possono alterare la stabilità e lo spazio di traffico richiesto."],"g2-wartungsbereich":["Ci sono barriere davanti ad un'area di manutenzione. Come ti stai comportando?","Il tuo percorso abituale è temporaneamente chiuso.","Sposta brevemente le barriere e attraversa inosservato.","Attraversare direttamente l'area di lavoro sotto carico.","Rispettare la chiusura e scegliere un percorso alternativo approvato.","Nelle aree delimitate non è consentito entrare o transitare senza autorizzazione."],"g2-bremsprobe":["Quando ha senso un test funzionale del freno di servizio?","Prepari il carrello elevatore prima del lavoro.","Come parte dell'ispezione richiesta prima dell'uso.","Eseguire solo dopo un incidente grave.","Solo se il camion ha già raggiunto l'alta velocità.","Prima dell'uso viene controllata la funzionalità degli impianti rilevanti per la sicurezza."],"g2-fahrzeuganhaenger":["Vuoi trainare un rimorchio con un carrello elevatore. Cosa è richiesto?","L'azienda sta pianificando il trasporto con un carico annesso.","Lega ogni rimorchio a una forca senza controllare.","Rispettare l'approvazione del produttore, l'accoppiamento adatto e il carico di trazione consentito.","Basta aumentare la pressione dei pneumatici e partire.","La circolazione dei treni è possibile in sicurezza solo nel rispetto delle specifiche tecniche e con un collegamento adeguato."],"g2-rueckfahrt":["Cosa è importante quando si fa retromarcia con il carrello elevatore?","C'è un'area confusa nel corridoio del magazzino.","Guarda sempre solo nello specchietto retrovisore, indipendentemente dall'ambiente circostante.","Guidare senza visibilità fintanto che il clacson è stato premuto una volta.","Osservare in sicurezza il percorso e la zona delle persone e, se necessario, istruirle.","La retromarcia richiede una visuale chiara o misure di sicurezza aggiuntive efficaci."],"g2-lastentnahme":["Prendi un pallet da uno scaffale alto. Cosa è giusto?","La tavolozza potrebbe non essere centrata.","Sollevare il carico in modo sicuro e stabilizzarlo prima di abbassarlo.","Lasciare che il pallet oscilli di lato mentre lo si estrae.","Controllare sotto il pallet sollevato per vedere se è danneggiato.","Il sollevamento e l'abbassamento controllati impediscono la caduta dei carichi e movimenti pericolosi."],"h2-absenkweg":["Perché l'area sotto una piattaforma di lavoro aereo deve rimanere libera?","Il cestello viene abbassato e sotto di esso vengono posizionati i materiali.","Premere i materiali verso il basso con il cestello.","Tenere d'occhio solo la zona dei piedi dell'operatore.","Evitare il rischio di schiacciamento e collisione durante l'abbassamento.","Nella zona di discesa non devono essere presenti persone o ostacoli che potrebbero rimanere intrappolati."],"h2-transporthoehe":["Come si sposta un palco mobile su un passaggio basso?","L'altezza da terra è inferiore a quella del braccio esteso.","Posizionare la piattaforma in una posizione di trasporto adeguata secondo le istruzioni per l'uso.","Lasciare il braccio esteso e spostarsi sotto il soffitto.","Premere il cestello contro il lato del telaio della porta.","Per gli spostamenti di traslazione l'altezza complessiva e la posizione di trasporto devono corrispondere alle specifiche del costruttore e al passaggio."],"h2-bodenoeffnung":["C'è un'apertura non protetta nel pavimento accanto al palco. Come reagisci?","Vicino all'apertura è presente un punto di guida o di appoggio.","Posizionare un supporto direttamente sul bordo dell'apertura.","Modificare il luogo di installazione oppure far controllare da un professionista la portata e il fissaggio.","Coprire il punto pericoloso solo con una scatola di cartone.","Le aperture e le aree marginali possono cedere sotto i carichi di supporto e devono essere adeguatamente prese in considerazione."],"h2-rettungsperson":["Perché una seconda persona deve conoscere la procedura di salvataggio?","Un operatore potrebbe restare incapace al vertice.","Quindi il lavoro nel paniere generalmente può svolgersi senza sicurezza.","In modo che il palco possa essere gestito più velocemente di quanto consentito.","In modo che in caso di emergenza possa essere avviato un salvataggio sicuro.","Un concetto di salvataggio deve tenere conto dell'assistenza a terra in caso di guasto o emergenza."],"h2-werkzeugabwurf":["Cosa vale per gli attrezzi in alta quota?","Un utensile allentato potrebbe cadere dal bordo del cestello.","Proteggere gli strumenti in modo che non costituiscano pericolo per nessuno o cadano.","Posiziona semplicemente gli strumenti sulla ringhiera per ridurre il carico.","Se necessario, buttare giù gli attrezzi dal cestino.","Gli oggetti che cadono mettono in pericolo le persone sottostanti; Il materiale deve essere immagazzinato in modo sicuro."],"h2-trittstufe":["Una scatola dovrebbe servire come spazio aggiuntivo nel cestino. Cosa è giusto?","Altrimenti raggiungerai a malapena il posto di lavoro.","Posiziona la scatola sulla ringhiera e sali su di essa.","Non salire su rilievi improvvisati; Utilizzare attrezzature di lavoro adeguate.","Caricare intenzionalmente il cestello oltre l'altezza consentita.","Rialzi improvvisati compromettono la protezione anticaduta prevista e non sono consentiti."],"h2-lastverteilen":["A cosa presti attenzione quando ci sono più persone nel cestino del lavoro?","Due persone lavorano nel cestello con attrezzi pesanti.","Giudicare il carico basandosi esclusivamente sulla dimensione dell'utensile.","Conservare gli attrezzi pesanti direttamente sulla ringhiera di protezione.","Non superare il carico consentito del cestello, comprese persone e strumenti.","La capacità di carico consentita comprende tutte le persone, i materiali e gli strumenti nel cestello."],"h2-abstuetzplatte":["Quando vengono presi in considerazione gli spessori aggiuntivi per i supporti?","Il pavimento di installazione può sopportare solo un carico limitato.","Se necessario per una distribuzione sicura del carico secondo le specifiche.","Per posizionare i supporti il ​​più vicino possibile al bordo di una fossa di costruzione.","Per utilizzare una portata più lunga senza le informazioni del produttore.","Sono necessarie aree di contatto sufficienti per forze di supporto sicure."],"h2-baugrube":["Un palco dovrebbe essere posizionato direttamente sul bordo di una fossa di costruzione. Cosa stai controllando?","Il sottosuolo potrebbe cedere lateralmente a causa del pozzo di scavo.","Estendere i supporti nello scavo.","Garantire una distanza di sicurezza e una capacità di carico sufficienti del sottosuolo.","Compensare il rischio solo sollevando lentamente il cestello.","Le fosse di scavo possono compromettere la stabilità a causa della pendenza e del cedimento del sottosuolo."],"h2-witterung":["Durante l'uso si forma della formazione di ghiaccio. Come ti comporti?","Le superfici di controllo e l'area di lavoro diventano lisce.","Alzare il palco per evitare neve e ghiaccio.","Ignorare gli avvisi finché la piattaforma è accesa.","Interrompere il lavoro e rivalutare le condizioni operative secondo le istruzioni operative.","I cambiamenti meteorologici possono modificare la responsabilità, l'operatività e i limiti di utilizzo sicuri."],"h2-aufbaukontakt":["Una struttura in acciaio limita il percorso del cestello. Cos'è importante?","Durante il sollevamento sussiste il rischio di schiacciamento tra il cestello e il supporto.","Pianifica i movimenti in modo che il tuo corpo e il canestro non rimangano intrappolati.","Fai il viaggio più velocemente in modo che il cestino passi più velocemente.","Spingere di lato la costruzione con il cestino.","I punti di pizzicamento tra la piattaforma e l'ambiente richiedono un'osservazione attenta e un movimento controllato."],"h2-sicherheitsabstand":["Quando è necessario delimitare l'area pericolosa di un palco?","Sotto il sito passa una linea di trasporto pubblico.","Solo se un oggetto è già caduto.","Se terzi potrebbero essere messi in pericolo dal movimento o dalla caduta di oggetti.","Mai, perché il cestino da lavoro previene sostanzialmente tutti i pericoli.","L'area sotto e adiacente al palco deve essere protetta dai pericoli prevedibili."],"h2-korbtor":["Cosa vale per la porta d'ingresso del cestino da lavoro?","Sei già all'altezza di lavoro.","Lascia la porta aperta così puoi uscire più velocemente.","Legare la porta permanentemente aperta con una corda.","Mantenere la porta chiusa secondo il meccanismo di bloccaggio fornito.","Le serrature fornite fanno parte delle misure di protezione contro la caduta dal cestello da lavoro."],"h2-energieleitung":["Cosa succede se una linea aerea non viene disattivata in modo sicuro?","Lavori con la piattaforma di lavoro aereo vicino a loro.","Garantire le distanze di sicurezza specificate e le misure di protezione necessarie.","Muovi il canestro proprio davanti alla linea finché non viene toccato.","Affidati ai pneumatici in plastica e lavora senza lacune.","Sono possibili scariche elettriche anche senza contatto diretto; Sono necessarie le distanze di sicurezza."],"h2-schwanken":["Il cestino da lavoro inizia a oscillare in modo insolitamente forte. Cosa è giusto?","Il movimento non è più controllato.","Riaggiustare in modo incontrollabile con rapidi contromovimenti.","Arrestare il movimento e verificare la causa o le condizioni operative.","Aggiungi altre persone al carrello per renderlo più pesante.","Vibrazioni insolite possono indicare condizioni operative inadeguate o un malfunzionamento."],"h2-ladegeraet":["Un cavo di ricarica per lo stadio ad azionamento elettrico è danneggiato. Cosa fai?","Durante il collegamento è visibile l'isolamento danneggiato.","Tocca il danno con guanti bagnati.","Premere la spina nella presa il più forte possibile.","Non avviare il processo di ricarica e far controllare il cavo da un professionista.","I cavi elettrici danneggiati comportano il rischio di scosse elettriche e incendi."],"h2-gelaenderanbau":["Puoi rimuovere tu stesso una ringhiera per avvicinarti?","Un componente impedisce alle persone di avvicinarsi al luogo di lavoro.","Non modificare o rimuovere autonomamente i dispositivi di protezione.","Dopo il sollevamento, svitare la ringhiera e installarla successivamente.","Continuare a lavorare senza ringhiera finché qualcuno è in piedi accanto ad essa.","I dispositivi di protezione strutturale non possono essere modificati senza specifiche ammissibili e senza misure di sostituzione sicure."],"h2-lastkran":["La piattaforma può essere utilizzata come gru per sollevare un carico?","Il materiale deve essere trasportato appeso liberamente accanto al cestello da lavoro.","Ogni volta che il peso è inferiore al proprio peso corporeo.","Solo se il produttore e l'apparecchio consentono espressamente questo uso speciale.","Basta attaccare un gancio alla ringhiera e sollevare il materiale.","Le piattaforme di lavoro aereo non sono automaticamente progettate per lavori con gru o carichi sospesi aggiuntivi."],"h2-arbeitsvorbereitung":["Cosa comporta la preparazione per una nuova sede?","Non conosci ancora il cantiere.","Basta stimare la distanza dal parcheggio più vicino.","Indipendentemente dall'ambiente circostante, estendilo completamente immediatamente.","Valutare i pericoli, il suolo, le vie di traffico, l'idoneità del soccorso e delle attrezzature.","Una valutazione dei rischi legati al luogo è un prerequisito per condizioni operative sicure."],"h2-kabelschlaufe":["Un cavo di alimentazione attraversa il percorso del palco. Cosa è giusto?","Il cavo potrebbe rimanere intrappolato durante il movimento.","Liberare la strada e proteggere i cavi elettrici da eventuali danni.","Utilizzare il cavo con le ruote come soglia stradale.","Sollevare il cestello senza controllare la superficie del pavimento.","I cavi investiti o schiacciati possono causare pericoli elettrici e meccanici."],"h2-leitungsnaehe":["Chi chiarisce le misure di protezione su un impianto elettrico?","La piattaforma dovrebbe funzionare vicino alle apparecchiature sotto tensione.","La persona nel cestino decide esclusivamente ad occhio.","Coinvolgere le autorità responsabili e attuare misure di protezione coordinate.","La distanza verrà determinata solo dopo l'inizio dei lavori.","Lavorare in prossimità di impianti elettrici richiede misure di protezione pianificate e coordinate."],"h2-funkkommunikation":["Perché i segnali tra il terreno e il canestro devono essere chiari?","Una persona a terra assiste nelle manovre.","In modo che più persone possano dare istruzioni contraddittorie contemporaneamente.","In modo che l'abbassamento di emergenza possa essere provato senza istruzioni.","In modo che i movimenti vengano eseguiti solo dopo una chiara comunicazione.","Una comunicazione chiara riduce i movimenti errati e le collisioni durante le manovre."],"h2-neuebedienung":["Passi a un diverso tipo di palcoscenico. Cosa è richiesto?","Le funzioni operative differiscono notevolmente.","Istruzioni specifiche del dispositivo prima dell'uso indipendente.","Basta leggere il logo dell'azienda sul dispositivo.","Un giro di prova con il cestino già esteso senza istruzioni.","La sola qualificazione non sostituisce l'istruzione relativa al tipo di dispositivo specifico."],"h2-steckanschluss":["Cosa dovresti controllare prima di collegare un caricabatterie?","È necessario caricare una piattaforma di lavoro aereo elettrica.","Utilizzare qualsiasi presa indipendentemente dalle condizioni e dal fusibile.","Controllare il collegamento adeguato e il cavo non danneggiato secondo le istruzioni del produttore.","Scollegare regolarmente la spina di alimentazione durante la ricarica.","Collegamenti elettrici adeguati e intatti proteggono da scosse elettriche e incendi."],"h2-absperrpersonal":["Una persona entra nell'area transennata durante i lavori di sollevamento. Cosa fai?","Puoi vedere una persona direttamente sotto il cestino del lavoro.","Continuare a guidare se la persona indossa il casco protettivo.","Lascia cadere uno strumento nella loro direzione come segnale di avvertimento.","Interrompere i movimenti pericolosi e far sgombrare l'area.","Una barriera non sostituisce la sorveglianza della zona pericolosa durante il funzionamento."],"k2-arbeitsplanung":["Cosa dovrebbe essere incluso nella preparazione del lavoro prima di un'operazione con la gru?","Il carico, l'ubicazione e il percorso di trasporto non sono ancora stati coordinati.","Sollevare prima il carico più pesante senza ulteriore pianificazione.","Segnare sul pavimento del corridoio solo il percorso più breve.","Chiarire in anticipo la portata, le imbracature, il percorso del carico e l'area pericolosa.","Uno spostamento pianificato della gru richiede un'adeguata movimentazione del carico, percorsi sicuri e misure di protezione coordinate."],"k2-hakenposition":["Come viene posizionato il gancio della gru sul carico prima del sollevamento?","I punti di attacco sono sotto la gru.","Il più verticalmente possibile sopra il baricentro in base alla battuta.","Spostarsi molto lateralmente in modo che il carico oscilli più rapidamente.","In ogni caso al bordo esterno del carico, indipendentemente dal baricentro.","L'applicazione verticale della forza e punti di ancoraggio adeguati riducono i movimenti laterali e incontrollati."],"k2-hakengabel":["Un gancio di carico mostra una deformazione evidente. Cosa si applica?","Il gancio appare piegato rispetto al suo stato abituale.","Piegare la deformazione indietro con il carico successivo.","Arrestare il funzionamento della gru e far controllare il gancio da un esperto.","Collegare solo carichi leggeri e continuare a lavorare.","La deformazione può compromettere la sicurezza del gancio; non è consentito un ulteriore utilizzo non autorizzato."],"k2-zugueberlast":["Il fardello è più pesante di quanto inizialmente ipotizzato. Cosa fai?","Durante la preparazione compaiono nuove informazioni sul peso.","Sostituire la riserva di sicurezza con un sollevamento più rapido.","Ignorare il peso del carico fissandolo su un altro punto.","Determinare il carico effettivo e ricontrollare i limiti di carico.","Un sollevamento sicuro richiede dati di carico affidabili e il rispetto di tutte le capacità di carico pertinenti."],"k2-arbeitskorb":["Un normale gancio per gru può trasportare facilmente le persone?","Una persona vuole raggiungere un posto di lavoro elevato.","No, il trasporto passeggeri richiede strutture e misure speciali consentite.","Sì, se la persona si tiene alla corda dell'imbracatura.","Sì, non appena la corsa viene eseguita particolarmente lentamente.","Il trasporto di persone è consentito solo alle condizioni speciali previste a tale scopo."],"k2-bruecke":["Un carroponte si muove lungo il percorso del corridoio condiviso. Cos'è importante?","I dipendenti restano sotto il percorso di trasporto.","Guidare con il carico appena sopra la testa dei dipendenti.","Mantenere efficacemente il percorso di carico e l'area di traffico libera e sicura.","Utilizzare solo il segnalatore acustico invece di ulteriori misure.","Le persone a rischio non devono trovarsi sotto carichi sospesi o nel percorso di trasporto."],"k2-zweitekrane":["Due gru lavorano in un'area sovrapposta. Cosa è necessario?","I bracci o i carichi potrebbero scontrarsi tra loro.","Entrambi gli operatori della gru lavorano contemporaneamente senza previo accordo.","I movimenti sono volutamente accelerati per evitare gli incroci.","Coordinare le operazioni e adottare misure adeguate per prevenire minacce reciproche.","Aree di lavoro sovrapposte richiedono un'organizzazione operativa coordinata e presidi adeguati."],"k2-pruefbuch":["Qual è il significato dell'ispezione periodica obbligatoria della gru?","La macchina viene utilizzata regolarmente nelle operazioni.","Integra il controllo operativo con la prescritta visita specialistica.","Sostituisce permanentemente qualsiasi ispezione visiva prima dell'inizio dei lavori.","È necessario solo dopo un incidente.","Le ispezioni ricorrenti e i controlli operativi continui hanno compiti diversi."],"k2-absetzflaeche":["L'area di posizionamento prevista non è uniforme. Come ti comporti?","Il carico potrebbe ribaltarsi durante il posizionamento.","Posiziona il carico su un angolo e lascialo pendere invariato.","Preparare fondi o superfici idonee, portanti e stabili.","Posizionare una persona sotto il carico durante l'abbassamento.","Le aree di posizionamento devono sostenere il carico in modo sicuro e impedire pericolosi movimenti di ribaltamento o rotolamento."],"k2-anfahrbereich":["Prima che la gru inizi a muoversi, è presente una persona nell'area di spostamento. Cosa fai?","Il percorso è bloccato da una persona.","Metti da parte la persona con un breve giro di prova.","Avviarsi utilizzando solo il finecorsa senza controllo visivo.","Iniziare il movimento solo quando la zona di pericolo è libera e sicura.","I movimenti di guida e di rotazione non devono costituire pericolo per le persone."],"k2-schlaffseil":["Perché la fune del paranco non dovrebbe allentarsi in modo incontrollabile quando viene appoggiata?","Il carico è acceso, il gancio viene abbassato ulteriormente.","In modo che la fune e i ganci non si incastrino o siano sottoposti a carichi incontrollati.","In modo che il carico possa poi essere tirato lateralmente dalla fune.","In modo che le brache si stacchino dal gancio.","Il passaggio incontrollato dei cavi può causare impigliamenti e movimenti pericolosi del carico."],"k2-pendel":["Un carico trasportato inizia a oscillare. Cosa è giusto?","Il carico si sposta lateralmente più del previsto.","Compensare con contromovimenti rapidi e a tutta velocità.","Ridurre gli spostamenti in modo controllato e tranquillizzare gli spostamenti senza persone nella zona di pericolo.","Tenere il carico oscillante a mani nude.","I carichi oscillanti possono influenzare le persone e le strutture; i movimenti calmi riducono il rischio."],"k2-funkakku":["Il radiocomando di una gru ha la batteria scarica. Cosa si applica?","Il collegamento potrebbe rompersi durante il sollevamento.","Sollevare rapidamente un carico prima che il controllo fallisca.","Se la connessione viene persa, spostare il carico tirando l'imbracatura.","Garantire una connessione di controllo affidabile prima dell'uso.","Controllo e comunicazione affidabili sono prerequisiti per i movimenti controllati della gru."],"k2-mehrereanschlaeger":["Due persone danno contemporaneamente segnali diversi all'operatore della gru. Cosa è giusto?","I segni si contraddicono tra loro.","Interrompere il movimento e chiarire chiaramente le responsabilità.","Preferire il segno della persona più lontana.","Continua il movimento secondo le tue sensazioni.","I conducenti di gru hanno bisogno di una comunicazione chiara e inequivocabile, soprattutto quando i percorsi di carico sono confusi."],"k2-endabschaltung":["Perché un finecorsa non dovrebbe essere utilizzato in modo improprio come normale limitazione della corsa?","Il carico viene spesso spostato fino alla distanza di sollevamento massima.","Gli interruttori di finecorsa generalmente consentono un sollevamento più rapido senza visibilità.","I finecorsa sono dispositivi di sicurezza e non sostituiscono il funzionamento controllato.","Dovrebbero essere colpiti il ​​più forte possibile ad ogni colpo.","I dispositivi di sicurezza servono a proteggere dai pericoli e non devono essere abusati come previsto."],"k2-wetterbeobachtung":["Il vento aumenta in modo significativo con un carico di ampia area. Cosa è richiesto?","Una vasta area dei componenti si comporta come una vela.","Sollevare sempre il carico più in alto in modo che il vento abbia meno effetto.","Sostituisci le imbracature con altre più sottili.","Valutare i limiti operativi e di vento e, se necessario, regolare il sollevamento.","Il vento può generare notevoli forze aggiuntive e movimenti pendolari, soprattutto con carichi di grandi dimensioni."],"k2-ortswechsel":["Cosa è importante quando si sposta una gru mobile in una nuova posizione?","Cambiano le condizioni del sottosuolo e del supporto.","Controllare la posizione e il supporto dello stand prima di riprendere il carico.","Applica le impostazioni dalla posizione precedente senza verificare.","Far regolare nuovamente il supporto durante il sollevamento.","Ciascuna posizione di installazione può avere condizioni di terreno e di carico di supporto diverse."],"k2-betriebsbereich":["Una gru dovrebbe funzionare dall'altra parte della strada. Cosa è necessario chiarire?","Terzi potrebbero entrare nella zona di pericolo.","Assicurare la strada solo con un clacson.","Obbligatori lockdown, votazioni e misure di protezione davanti all'hub.","Sollevare il carico sui veicoli il più rapidamente possibile senza fissarlo.","Una gestione sicura del traffico previene rischi eccessivi per terzi derivanti dai carichi e dai movimenti delle gru."],"k2-hochheben":["Dopo il sollevamento di prova, il carico pende chiaramente storto. Cosa è giusto?","Apparentemente il focus è stato mal valutato.","Continua a sollevare in modo che lo squilibrio si corregga da solo.","Chiedi a una persona di tirare il carico pendente.","Appoggiare il carico in modo sicuro e controllare nuovamente l'attacco e il baricentro.","Il sollevatore di prova viene utilizzato per rilevare attacchi errati e posizioni di carico instabili prima del trasporto."],"k2-schwebelast":["È possibile lasciare incustodito un carico sollevato?","Il turno finisce, ma il carico è ancora sul gancio.","No, abbassa il carico in sicurezza e fissa adeguatamente la gru.","Sì, se la gru è bloccata contro l'allontanamento.","Sì, purché sul terreno sia presente un segnale di avvertimento.","In linea di principio i carichi sospesi non dovrebbero essere lasciati incustoditi."],"k2-mitnahme":["Un collega vuole viaggiare su una gru caricata. Cosa si applica?","Il carico dovrebbe essere trasportato in un punto più alto.","La guida è consentita se il collega indossa il casco.","Le persone non possono essere trasportate o agganciate ai carichi normali.","Un passaggio è sempre consentito purché il collega sia noto al gruista.","Il trasporto di persone insieme a carichi comporta notevoli rischi di caduta e schiacciamento."],"k2-warnsignal":["Un sistema di allarme operativo sulla gru si guasta. Cosa è giusto?","Non è più possibile avvisare prima della partenza.","Ignorare il sistema quando il motore è in funzione.","Sostituire permanentemente l'avviso toccando l'alloggiamento.","Segnalare un guasto rilevante per la sicurezza e interrompere il funzionamento secondo le istruzioni.","I dispositivi di allarme richiesti devono essere funzionali in modo da proteggere le persone in modo tempestivo."],"k2-schneekante":["Una gru mobile deve essere supportata su un terreno ghiacciato e irregolare. Cosa si applica?","Il terreno potrebbe perdere la sua capacità portante durante il disgelo.","Valutare la capacità di carico e la situazione del supporto in condizioni reali.","Il terreno ghiacciato ha sempre una capacità portante.","Posizionare i supporti solo su piccole pietre.","La temperatura, l'umidità e la struttura del sottosuolo influenzano la capacità di carico delle posizioni delle gru."],"k2-laufkatze":["Un carrello si muove verso un ostacolo. Come ti comporti?","C'è un oggetto nell'area di guida.","Spingere via lentamente l'oggetto con il carico.","Arrestare tempestivamente il movimento e rimuovere l'ostacolo in modo sicuro.","Superare l'ostacolo a velocità maggiore.","I movimenti della gru devono essere guidati in modo tale che non si verifichino collisioni con ostacoli."],"k2-anschlagaufnahme":["Dovresti sollevare un carico utilizzando un occhiello non designato. Cosa è giusto?","L'occhiello può essere destinato solo al montaggio di una copertura.","Ogni occhiello è adatto al carico completo della gru.","Caricare l'occhiello solo con due persone contemporaneamente.","Verificare la capacità di carico e l'idoneità del punto di ancoraggio prima dell'uso.","Non tutti gli occhielli esistenti costituiscono un punto di attacco stabile per i carichi della gru."],"l2-seilbruch":["Una fune metallica presenta diversi fili singoli rotti. Cosa è giusto?","I punti di rottura si trovano nella zona della fune portante.","Non continuare a utilizzare l'attrezzatura di sollevamento e farla valutare da un professionista.","Piega indietro le estremità del filo a mani nude.","Continuare ad utilizzare la corda se il carico è particolarmente leggero.","Le rotture dei fili possono essere un criterio di scarto; Le corde danneggiate devono essere valutate professionalmente."],"l2-schaekel":["Cosa è fondamentale quando si utilizza un grillo?","Un grillo collega l'imbracatura e il carico.","Sostituisci il bullone con un chiodo qualsiasi.","Verificare la capacità di carico adeguata, le condizioni non danneggiate e i bulloni corretti.","Stimare la capacità di carico in base al colore.","I grilli devono essere di dimensioni adeguate, utilizzati completamente e nella direzione di carico prevista."],"l2-tragfaehigkeit":["Cosa devi considerare quando usi più fili?","I fili corrono ad angolo rispetto alla verticale.","Basta aggiungere la capacità di carico di ciascun filo come desiderato.","Appendi il carico solo sul filo più leggero.","Prendere in considerazione la capacità di carico dell'intero tipo di ancoraggio e di angolo.","L'angolo di inclinazione e il numero effettivo di trefoli influiscono notevolmente sul carico consentito."],"l2-schweissnaht":["È possibile saldare un punto di ancoraggio improvvisato a un carico?","Non esistono punti di raccolta designati idonei per il carico.","Utilizzare solo punti di ancoraggio adeguatamente progettati e approvati.","Qualsiasi cordone di saldatura è sufficiente senza test.","Inserire un gancio attraverso un'apertura nella lamiera.","I punti di ancoraggio devono essere idonei alle forze coinvolte nel sollevamento."],"l2-einseitig":["Un carico è notevolmente più pesante su un lato. Come procedi?","Il centro di gravità si trova all'esterno del centro geometrico.","Lasciare tutte le ciocche della stessa lunghezza indipendentemente dal centro di gravità.","Determinare il centro di gravità e regolare la posizione di conseguenza.","Per prima cosa sollevare il carico alla massima altezza di sollevamento.","Se il centro di gravità è decentrato, i carichi possono ribaltarsi inaspettatamente o i singoli trefoli possono essere sovraccaricati."],"l2-kettenriss":["Cosa vale per una braca a catena con crepe visibili?","C'è una crepa in una delle maglie della catena.","Segna la fessura con la vernice e sollevala senza modifiche.","Avvolgi il collegamento con il filo e riutilizzalo.","Rimuovere immediatamente la catena e informare la persona responsabile.","Le crepe nelle maglie delle catene portanti rappresentano danni rilevanti per la sicurezza e richiedono la messa fuori servizio."],"l2-lastfuehrung":["Come si trasporta un carico di grandi dimensioni quando esiste il rischio di rotazione?","Il carico può oscillare lateralmente durante il sollevamento.","Utilizzare dispositivi di guida adeguati e mantenere la distanza di sicurezza.","Tenere il carico direttamente tra le mani durante la guida.","Passare sotto il carico e allinearlo dal basso.","La guida del carico non deve causare l'ingresso di mani o corpi nella zona pericolosa."],"l2-schnueren":["Cosa è importante quando si allacciano i lacci?","L'imbracatura viene guidata attorno a un componente.","Assumere la stessa capacità di carico di qualsiasi altro tipo di ancoraggio.","Osservare l'idoneità del tipo di attacco e il carico consentito secondo la marcatura.","Tirare insieme l'imbracatura in qualsiasi misura senza controllare.","Il tipo di attacco per allacciatura può modificare la capacità di carico consentita e deve essere utilizzato correttamente."],"l2-winkelmesser":["Perché non puoi ignorare un angolo del filo piatto?","Due linee di imbracatura corrono quasi orizzontalmente rispetto al carico.","Un angolo piatto rende automaticamente il filo più forte.","Il carico è sempre distribuito equamente indipendentemente dall'angolo.","Forze elevate sui trefoli possono superare la capacità di carico consentita.","All’aumentare dell’angolo rispetto alla verticale, aumentano le sollecitazioni sui trefoli."],"l2-heisse-last":["Cosa è necessario controllare per un carico caldo?","Una parte in acciaio è stata recentemente trattata termicamente.","Rispettare i limiti di temperatura delle imbracature e la scelta adeguata.","Ogni imbracatura tessile può resistere a qualsiasi temperatura.","L'etichettatura non ha importanza quando fa caldo.","La temperatura può influenzare la capacità di carico consentita delle imbracature."],"l2-abstand":["Riesci a mettere le dita sotto il carico quando lo appoggi?","Il carico dovrebbe atterrare su una superficie con precisione millimetrica.","Sì, se indossi guanti da lavoro.","No, mantieni le distanze e utilizza ausili adeguati.","Sì, se il movimento della gru è particolarmente lento.","Parti del corpo tra il carico e la base potrebbero rimanere intrappolate."],"l2-verbindung":["Un anello di collegamento della catena dell'imbracatura non è bloccato. Cosa si applica?","Manca il dispositivo di fissaggio.","Usa il chiavistello senza serratura quando nessuno guarda.","Sigillare l'elemento con nastro adesivo.","Non colpire finché il dispositivo di fissaggio non è adeguatamente fissato.","Gli elementi di collegamento devono essere fissati completamente e in conformità con la loro progettazione."],"l2-lasthaken":["Cosa controlli quando sei appeso al gancio di una gru?","Nel gancio devono essere inserite più imbracature.","Garantire la vestibilità sicura e l'idoneità dei ganci e delle sospensioni.","Posizionare le imbracature sulla punta del gancio.","Sostituire il blocco del gancio con una fascetta per cavi.","La forza deve essere applicata come previsto nelle aree designate."],"l2-fasern":["Una cinghia di sollevamento presenta un grave irruvidimento e danni alle fibre. Cosa è giusto?","Le fibre di sostegno sono visibilmente danneggiate.","Copri il danno con un altro nodo.","Separare la cinghia di sollevamento e farla controllare da uno specialista.","Quindi sollevare il carico più rapidamente.","Le fibre portanti danneggiate possono ridurre significativamente la capacità di carico di una cinghia di sollevamento."],"l2-anheben":["Cosa vale subito dopo il primo centimetro di sollevamento?","Il carico si sta appena sollevando dalla base.","Tirare il carico alla sua massima altezza senza controllo.","Controllare sotto carico se le imbracature sono tese.","Controllare la posizione dell'arresto, l'equilibrio e il comportamento del movimento.","Un sollevamento di prova controllato rende visibili le possibili instabilità prima del successivo trasporto."],"l2-lastgewichte":["Il peso del carico è sconosciuto. Cosa è giusto?","Il componente non ha alcuna indicazione del peso.","Determinare il peso caricabile prima di selezionare le imbracature.","Stimare il peso in base al colore del carico.","Utilizzare qualsiasi imbracatura a doppia lunghezza.","Senza un peso noto o determinato in modo affidabile non è possibile verificare con certezza l'idoneità delle imbracature."],"l2-lose-teile":["Sul carico da sollevare sono presenti attrezzi sciolti. Cosa fai?","Gli strumenti potrebbero cadere durante il sollevamento.","Tenere gli attrezzi con una mano durante la guida.","Rimuovere o fissare efficacemente gli oggetti sciolti prima del sollevamento.","Sollevare il carico un po' più velocemente in modo che nulla scivoli.","Gli oggetti sciolti possono cadere e mettere in pericolo le persone presenti nella zona."],"l2-wind":["Un grande carico è attaccato in caso di vento forte. Cosa si applica?","Il componente offre al vento un'ampia superficie da attaccare.","Sollevare il carico senza considerare i movimenti oscillanti.","Altre persone dovrebbero sostenere direttamente il carico.","Valutare le condizioni del vento e astenersi dal sollevare se la situazione non è sicura.","Le forze del vento possono influenzare la guida del carico e la stabilità durante il trasporto."],"l2-unterlage":["Perché sono importanti i documenti idonei durante lo svezzamento?","Un carico rotondo rotolerebbe a terra.","Posizionare saldamente il carico e assicurarlo contro il rotolamento, se necessario.","Lasciare il carico direttamente sulle imbracature.","Spingere i documenti sotto il carico solo dopo averli appoggiati.","Appositi supporti evitano ribaltamenti e movimenti indesiderati durante la deposizione."],"l2-transportweg":["Cosa è necessario coordinare prima del trasporto del carico?","Il carico viene spostato su più aree di lavoro.","Solo la durata prevista dell'hub.","Percorso di carico sicuro, comunicazione e barriere necessarie.","Una persona dovrebbe mostrare la strada sotto il carico.","Il trasporto di carichi richiede percorsi di traffico sicuri e un chiaro coordinamento."],"l2-schutzschlauch":["A cosa bisogna prestare attenzione quando si utilizzano imbragature con tubo protettivo?","Una fascia giace contro un bordo ruvido.","Qualsiasi panno sottile sostituisce un'adeguata protezione dei bordi.","Un tubo protettivo rimuove qualsiasi limite di carico consentito.","Selezionare i dispositivi di protezione in base all'idoneità e ai requisiti dell'applicazione.","I dispositivi di protezione devono essere adatti al materiale, al bordo e al carico previsto."],"l2-reinigung":["Una cinghia di sollevamento è stata contaminata da una sostanza chimica sconosciuta. Cosa è giusto?","Il nastro non può più essere valutato chiaramente.","Interrompere l'uso e chiarire la compatibilità o la condizione in modo professionale.","Pulire con qualsiasi solvente e continuare a sollevare immediatamente.","Ignora la sostanza chimica mentre il nastro è asciutto.","Le sostanze chimiche possono influenzare la resistenza delle imbracature tessili."],"l2-aufhaengung":["Cosa controlli per più fili sul collegamento di sospensione?","Due fili sono posti insieme in una sospensione.","Un filo può spostarsi nella punta dell'amo a piacimento.","Tutti gli elementi di collegamento devono essere adatti e disposti come previsto.","Per piccoli carichi è possibile utilizzare un anello con fessura.","Gli elementi di battuta e di collegamento devono essere portanti e disposti correttamente."],"l2-einweiserrolle":["Cosa succede se l'aggressore e il gruista non hanno linea di vista?","Un corriere blocca la vista del punto di consegna.","Coordinarsi chiamando più persone senza responsabilità.","Spostare il carico in base al rumore senza istruzioni.","Organizzare una comunicazione chiara e sicura e interromperla se non è chiara.","La mancanza di visibilità deve essere compensata da un coordinamento efficace e da una comunicazione sicura."],"l2-ausserbetrieb":["È stata riparata un'imbracatura danneggiata. Cos'altro è importante?","Rimane liberamente accessibile insieme alle risorse pronte per l'uso.","Proteggere da un ulteriore utilizzo accidentale e informare la persona responsabile.","Restituire il prodotto non contrassegnato all'inventario.","Riutilizzatelo solo quando trasportate un carico particolarmente leggero.","Le imbracature scartate devono essere protette in modo affidabile prima di un ulteriore utilizzo."],"b2-schwenkradius":["Perché il raggio di rotazione posteriore di un escavatore è fondamentale?","La coda si muove su un'area di lavoro limitata.","Terzi possono rimanere intrappolati nella sovrastruttura oscillante.","Il raggio di rotazione non ha alcuna influenza sulle persone vicine alla macchina.","La parte posteriore si muove sempre e solo nella direzione di marcia.","Durante la rotazione si crea una zona pericolosa anche dietro la macchina."],"b2-verkehrseinweiser":["Come viene assicurato il movimento di guida quando la visibilità è oscurata?","Un escavatore deve manovrare dietro un ostacolo.","Guidare senza vedere i segnali del segnalatore.","Se necessario, organizzare istruzioni appropriate con una comunicazione chiara.","Assicurare la retromarcia suonando il clacson solo una volta.","Percorsi confusi richiedono misure efficaci per prevenire collisioni e intrappolamenti."],"b2-standplatz":["Cosa vale per il supporto di un escavatore in pendenza?","Il pavimento è inclinato e potrebbe essere scivoloso.","La macchina può estendersi a piacimento con qualsiasi inclinazione.","Posizionare sempre l'escavatore su uno strato di terreno sciolto.","Verificare la stabilità ed i limiti di funzionamento della macchina prima dell'uso.","La pendenza del pendio e il sottosuolo hanno un'influenza significativa sulla stabilità."],"b2-oberleitung":["Perché è necessario pianificare la distanza della barra dalle linee elettriche?","Il braccio può avvicinarsi al cavo durante la rotazione.","La scarica elettrica è possibile anche senza contatto diretto.","Solo la benna può condurre l'elettricità, non il braccio.","Con terreno asciutto ogni distanza è automaticamente sicura.","Limiti di utilizzo e distanze di protezione devono essere chiariti prima di avvicinarsi agli impianti elettrici."],"b2-fremdperson":["Un passante entra nel cantiere nella zona panoramica. Cosa è giusto?","La persona si trova improvvisamente vicino alla benna dell'escavatore.","Sollevare la pala e farla oscillare sopra la persona.","Interrompere immediatamente il movimento e far sgombrare l'area.","Continua a osservare la persona dal finestrino laterale.","Le persone che si trovano nella zona pericolosa non devono essere messe in pericolo dai movimenti di lavoro."],"b2-parkstellung":["Come si mette in sicurezza una macchina movimento terra una volta terminato il lavoro?","L'escavatore rimane incustodito nel cantiere.","Lasciare il cucchiaio all'altezza della testa.","Lasciare girare il motore incustodito.","Riporre l'attrezzatura di lavoro, mettere in sicurezza la macchina e impedirne l'uso non autorizzato.","Un parcheggio adeguato riduce gli spostamenti accidentali e gli accessi non autorizzati."],"b2-eigenlast":["Perché i limiti delle attrezzature sono cruciali durante il sollevamento con un escavatore?","È necessario caricare un carico pesante sul braccio.","In caso contrario, la stabilità e la capacità di carico consentita potrebbero essere superate.","Qualsiasi macchina può sollevare qualsiasi carico purché la benna sia adatta.","Solo la lunghezza della fune dell'imbracatura determina il rischio.","Le informazioni sulla capacità di sollevamento e di carico dipendono dall'attrezzatura e dalla situazione applicativa."],"b2-untergrundhohlraum":["Il pavimento sopra un vecchio seminterrato potrebbe essere cavo. Cosa fai?","Dovresti guidare l'escavatore nell'area.","Attraversa il punto con il massimo slancio.","Prima di proseguire chiarire la capacità di carico e le eventuali cavità.","Basta posizionare un carico pesante sulla superficie.","Le cavità possono collassare sotto il peso della macchina e provocarne lo schianto."],"b2-feuchtigkeit":["Dopo forti piogge l'argine diventa molle. Cosa è giusto?","Un escavatore lavora in prossimità del bordo del terrapieno.","Avvicinare la macchina al bordo per aumentare la portata.","Ignorare le modifiche fino alla fine del turno.","Rivalutare le condizioni del suolo e di stabilità.","La penetrazione dell'umidità può modificare la capacità portante e la stabilità degli argini."],"b2-bodenprobe":["Perché i progetti delle condutture devono essere controllati prima dello scavo?","I cavi potrebbero passare sotto lo scavo previsto.","In modo da poter identificare le linee e pianificare misure di sicurezza adeguate.","In questo modo lo scavo può essere effettuato più rapidamente, indipendentemente da sistemi di terze parti.","Perché le macchine non devono mai essere utilizzate vicino ai cavi.","Le linee di alimentazione sotterranee richiedono un chiarimento affidabile della posizione prima dei lavori di scavo."],"b2-maschinenzugang":["Cosa vale quando si sale e si scende dalla macchina movimento terra?","La macchina si trova su un terreno irregolare.","Far scorrere la linea idraulica fuori dalla cabina.","Utilizzare i gradini designati e garantire un appoggio sicuro.","Salta sul braccio girevole mentre la macchina è in funzione.","Salite sicure e punti di sosta adeguati riducono il rischio di cadute e schiacciamenti."],"b2-kupplung":["Come si controlla una nuova terna dopo l'installazione?","La benna è collegata tramite l'attacco rapido.","Giudica visivamente il cucchiaio solo da una distanza maggiore.","Passa direttamente sotto il cucchiaio rialzato.","Garantire il corretto bloccaggio e le fasi di controllo prescritte.","Gli accessori bloccati in modo errato possono staccarsi e mettere in pericolo le persone."],"b2-hydraulikwartung":["Perché le linee idrauliche non possono essere aperte sotto pressione?","È necessario sostituire un tubo.","Il fluido che fuoriesce può causare gravi lesioni a causa dell'alta pressione.","La pressione impedisce sempre la fuoriuscita dell'olio.","Una linea aperta può essere controllata in sicurezza con le mani.","Il fluido ad alta pressione può penetrare nei tessuti e richiede uno scarico sicuro della pressione."],"b2-fahrweg":["Devi guidare su un ponte di costruzione temporaneo. Cosa stai controllando?","Il ponte è progettato solo per determinati carichi.","Se il colore del ponte corrisponde alla macchina.","Capacità di carico e idoneità al peso e alle dimensioni della macchina.","Solo se un'auto leggera è già passata sul ponte.","Le strutture temporanee possono essere utilizzate solo nell'ambito della loro comprovata capacità portante."],"b2-baggertransport":["Cosa è importante quando si trasporta un escavatore su un pianale ribassato?","La macchina viene portata al cantiere successivo.","Lasciare che l'attrezzatura di lavoro sporga liberamente oltre il bordo.","Tenere la porta della cabina aperta durante la guida.","Fissare la macchina secondo le specifiche di trasporto e controllare l'attrezzatura di carico.","I dispositivi di sicurezza per il trasporto e le adeguate strutture di carico impediscono scivolamenti e cadute."],"b2-schaufelfuellung":["Perché una pala gommata non può procedere velocemente con la benna sollevata in alto?","Il carico è pesante e il terreno è irregolare.","Un baricentro alto può aumentare il rischio di ribaltamento e problemi di visibilità.","La benna si stabilizza automaticamente alle alte velocità.","L'altezza della pala è irrilevante per la stabilità.","Un baricentro rialzato in genere peggiora la stabilità durante la guida e in curva."],"b2-fussgaenger":["Come ti comporti quando manovri accanto ai pedoni?","Anche l'accesso al cantiere è pedonale.","Usa la pala per dirigere i pedoni di lato.","Effettuare il movimento di guida solo quando l'area è sgombra e gestibile in sicurezza.","Basta suonare il clacson una volta e guidare lentamente senza visibilità.","Il traffico di veicoli e passeggeri deve essere efficacemente separato o coordinato in modo sicuro."],"b2-ueberlastwarnung":["Durante il sollevamento la macchina segnala un sovraccarico. Cosa fai?","Un carico sollevato raggiunge i limiti consentiti.","Disattivare l'avviso e continuare ad aumentarlo senza modifiche.","Stringere improvvisamente il carico mentre la macchina è in funzione.","Arrestare i movimenti pericolosi e correggere in sicurezza la situazione di carico.","Gli avvisi di sovraccarico indicano possibili violazioni dei limiti e rischi per la stabilità."],"b2-wasserleitung":["Durante gli scavi viene scoperto un tubo sconosciuto. Cosa si applica?","La linea non è riportata nei piani di costruzione.","Interrompere i lavori nell'area interessata e far identificare la linea da un professionista.","Prova a spostare la linea con la pala dell'escavatore.","Continua a scavare direttamente sotto la linea senza controllare.","Linee sconosciute possono causare pericoli elettrici, legati al gas o all'acqua."],"b2-hangefahrt":["Come si guida un escavatore su un pendio ripido?","Il percorso previsto si snoda lungo un pendio.","Attraversare il pendio indipendentemente dai limiti del produttore.","Rispettare l'inclinazione consentita e lo stile di guida prescritto della macchina.","Spostare il braccio molto verso l'esterno per bilanciare il veicolo.","La pendenza consentita dipende dalla macchina, dalla superficie e dalle informazioni del produttore."],"b2-schlechtebeleuchtung":["Quando si lavora in una fossa buia, la visibilità è inadeguata. Cosa è giusto?","Difficilmente puoi vedere persone e ostacoli.","Aumenta la velocità di scavo per completare rapidamente l'operazione.","Non utilizzare le luci mentre il motore è in funzione.","Interrompere il lavoro finché le zone pericolose non sono sufficientemente visibili.","Per i movimenti controllati della macchina è necessaria una visibilità sicura delle aree di guida e di lavoro."],"b2-kettenverschleiss":["Durante il controllo quotidiano si nota un cingolo danneggiato. Cosa fai?","Un collegamento a catena mostra evidenti danni.","Non continuare ad utilizzare la macchina in modo incontrollato e segnalare eventuali danni.","Continuare a guidare ad alta velocità in modo che la catena si raddrizzi.","Continuare a lavorare solo su terreni morbidi senza controllare.","I danni all'azionamento possono compromettere la controllabilità e la stabilità."],"b2-ladearbeiten":["Carichi un camion con l'escavatore. Cos'è importante?","L'autista del camion rimane vicino all'area di carico.","Far oscillare il secchio sopra la cabina di guida non protetta.","Impedire alle persone di rimanere nell'area pericolosa e coordinare i processi.","Inizia il caricamento senza comunicare con l'autista.","Durante il caricamento sussiste il pericolo di caduta di materiale e movimenti oscillanti."],"b2-arbeitsunterbrechung":["Interrompi i lavori di scavo per una riunione. Cosa si applica?","La macchina dovrebbe restare ferma per diversi minuti senza essere utilizzata.","Lascia la pala sollevata come segno.","Lasciare la macchina incustodita con la trazione inserita.","Appoggiare l'attrezzo in modo sicuro e assicurare la macchina contro l'uso involontario.","Anche le brevi interruzioni richiedono uno stato sicuro della macchina."],"b2-rollmaterial":["Il materiale sfuso può cadere durante il trasporto con la pala gommata. Cosa è giusto?","Il caricatore si avvicina ai dipendenti.","Raccogli il carico in sicurezza e scegli uno stile di guida sicuro con una posizione della pala adeguata.","Sollevare la pala il più in alto possibile in modo che l'area circostante abbia una visione chiara.","Raccogli il carico senza limitare il riempimento della benna.","Carichi sciolti, posizioni elevate della benna e scarsa visibilità possono mettere in pericolo le persone e il traffico."]};
